pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early on, but allow it if fitting_bins_count is low
    // to avoid fragmenting bins too early.
    let mut score = post_residual as f64;

    // Non-linear penalty for creating "dead space" (small residuals that likely can't fit future items)
    // We penalize residuals in the (0, 10) range exponentially as they are highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64).powf(2.5);
    }

    // Dynamic pressure: If we have many open bins, prioritize tightening existing ones (lower residual).
    // If we have few bins, prioritize keeping residuals larger to accommodate future items.
    let open_bins_factor = open_bins_count as f64 / 10.0;
    score += (post_residual as f64 * open_bins_factor * 0.5);

    // Lookahead logic: If the next item is large, avoid leaving a small post_residual.
    if next_item_size > 0 {
        let gap = post_residual as i32 - next_item_size as i32;
        if gap < 0 && post_residual < next_item_size {
            // This bin will likely not fit the next item; penalize this bin slightly.
            score += 15.0 * (1.0 - progress);
        }
    }

    // New Bin Logic:
    if is_new_bin {
        // Only open a new bin if the fitting_bins_count is low or if current fit quality is abysmal.
        // As progress increases, we become more willing to open new bins to pack tightly.
        let threshold = 40.0 + (progress * 30.0);
        score = threshold + (mean_residual * 0.5);
    } else {
        // For existing bins, reward bins that are closer to the mean_residual to maintain uniformity.
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (small gaps that are hard to fill).
    // Gaps between 1 and 9 are often useless given the item range.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item fits perfectly into this post_residual, 
    // reward this placement heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact fit (zero waste after next item)
            if post_residual == next_item_size {
                score -= 40.0;
            } else {
                // Reward residual space that is still usable for the next item
                score -= 20.0 * (next_item_size as f64 / post_residual as f64);
            }
        } else {
            // If next item does not fit, penalize if we are creating a gap that is 
            // slightly smaller than the next item (wasted potential).
            score += 10.0;
        }
    }

    // 3. Prevent opening new bins prematurely.
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless there are no good fits in existing bins.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have very few open bins, opening a new one is less costly.
        score -= open_bins_count as f64 * 0.5;
    }

    // 4. Balance: Favor bins that stay close to the current mean_residual 
    // to keep bin levels uniform (Best Fit Decreasing logic).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Urgency: If this is the last chance to fit an item (fitting_bins_count == 1),
    // prioritize this bin to avoid fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

