        if post_res >= next_item_size as f64 { -20.0 } else { 15.0 }
    } else {
        -post_res * 0.5
    };

    // Global state awareness: 
    // As the stream progresses, become more aggressive in packing to minimize open bins.
    let packing_pressure = progress * 40.0 * (open_bins_count as f64).sqrt();

    // Base score: prioritize smaller post_residuals (Best Fit), adjusted by the factors above.
