        // If no bins can fit the item, lower the penalty to force a new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (small residuals that likely won't fit future items)
    // We penalize residuals in the [1, 15] range heavily as they are hard to fill.
    if post_residual > 0 && post_residual < 16 {
        score += 40.0 * (16.0 - post_residual as f64);
    }

    // 2. Lookahead logic: If the next item can fit in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Global state awareness: Favor filling bins that are already "below average" in fullness
    // to keep the distribution of residuals uniform and avoid fragmentation.
    let fullness_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let mean_fullness = 1.0 - (mean_residual / bin_capacity as f64);
    if fullness_ratio > mean_fullness {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // 4. New bin thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if the 
    // alternative is creating a very poor fit in an existing bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        score = 45.0;
        // If there are no existing bins that fit the item, lower the cost to open one.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // As we reach the end of the stream, prioritize closing bins over opening new ones.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 30.0;
    } else {
        // 5. If this is an existing bin, reward it if it's the only one that fits.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize opening new bins heavily early on, but allow flexibility as the stream progresses.
    // The core objective is to minimize post_residual (Best Fit), but we apply non-linear
    // corrections to avoid creating "dead zones" (residuals too small for common items).

    let mut score = post_residual as f64;

    if is_new_bin {
        // A new bin is only desirable if we have many open bins already or if fitting_bins_count is low
        // and the current filling strategy would leave a poor residual in existing bins.
        score = 45.0 + (progress * 20.0) - (open_bins_count as f64 * 0.5);
    } else {
        // Penalty for creating a "sliver": residuals between 1 and 9 are often unusable.
        if post_residual > 0 && post_residual < 10 {
            score += 35.0 * (1.0 - progress);
        }

        // Favor bins where the post_residual is closer to the mean_residual of other bins
        // to keep bin fill levels balanced across the collection.
        score += (post_residual as f64 - mean_residual).abs() * 0.2;

        // Lookahead heuristic: if the next item is large, avoid leaving a small post_residual.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 * (next_item_size as f64 / bin_capacity as f64);
        }

        // If this is the only bin that can fit the item, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize leaving small gaps that are unlikely to fit future items.
    // If post_residual is < 10, it is almost certainly unusable space (since min size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary, but penalize cluttering too many bins.
    // If this is a new bin, apply a threshold penalty based on the current average space utilization.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have many open bins, make it slightly cheaper to open a new one if it improves packing density.
        score -= (open_bins_count as f64) * 0.5;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, prioritize it to avoid new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Efficiency: If the post_residual is exactly 0, it is a perfect fit.
    if post_residual == 0 {
        score -= 20.0;
    }

    // 6. Distributional Adjustment: Favor bins that stay closer to the mean residual to maintain uniform packing.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1306: Harmonic-Residual-Lookahead (HRL)
    // Minimizes score to prioritize placement.

    let mut score = post_residual as f64;

    // 1. Penalize fragmentation (dead space smaller than the smallest likely item)
    // If post_residual is small but > 0, it's often a "poison" bin.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class Logic: Reward placements that leave residuals matching potential future needs
    // We prioritize keeping the residual as a multiple of common item size clusters (e.g., ~20, 25, 33)
    let residual_penalty = (post_residual as f64 % 25.0).abs();
    score += residual_penalty * 0.5;

    // 3. Lookahead Integration: If next_item_size is large, avoid creating a residual too small for it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // 4. Fitting Constraint: If this is the only bin that fits the item, reward it heavily
    // to prevent unnecessary creation of new bins.
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // 5. New Bin Logic: Only open a new bin if the mean residual of current bins is already very low
    // (meaning we have no good space left) OR if we are at the very beginning of the stream.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 10.0;
        } else if mean_residual < 15.0 {
            score -= 5.0;
        } else {
            // Heavily penalize opening a new bin if good space exists
            score += 60.0;
        }
    }

    // 6. Dynamic Scaling: As the stream progresses, become more conservative about opening new bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Harmonic/Modulo logic focusing on Best-Fit Decreasing tendencies 
    // while penalizing small "sliver" residuals that cannot fit common future items.

    let mut score = post_residual as f64;

    // 1. Harmonic penalty: Heavily penalize residuals that are too small to fit 
    // the most likely future items (modeled here by next_item_size).
    // If post_residual is between 1 and next_item_size, it's a "fragmentation trap".
    if post_residual > 0 && post_residual < next_item_size {
        score += 50.0 + (next_item_size - post_residual) as f64 * 2.0;
    }

    // 2. Modulo-based "perfect fit" reward:
    // If post_residual is 0, this is a perfect fit.
    if post_residual == 0 {
        score -= 25.0;
    }

    // 3. Multi-bin management:
    // If this is the only bin that can fit the item, we are forced to use it.
    // Lower the score to ensure it is chosen over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // 4. New bin thresholding:
    // If we are considering a new bin (bin_residual == bin_capacity), 
    // we only pick it if the score is very low (i.e., we are desperate).
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is already very small,
        // suggesting that current bins are too fragmented to be useful.
        score += 40.0;
        score += mean_residual * 0.5;
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, prioritize closing bins (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) more heavily as the stream progresses
    // to force tighter packing later in the sequence.
    let dead_space_penalty = (1.0 - (post / bin_capacity as f64)).powf(2.0) * (1.0 + progress * 5.0);

    // Reward bins that can accommodate the next item (lookahead)
    let lookahead_reward = if next_item_size > 0 && post_residual >= next_item_size {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalty for opening a new bin: Only take if post_residual is very close to capacity
    // or if fitting_bins_count is 0.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            0.0 // Necessary
        } else {
            // Discourage new bins if existing ones can fit the item
            35.0 + (progress * 20.0)
        }
    } else {
        0.0
    };

    // Interaction term between current bin health and global state
    let state_coupling = (mean_residual - post) * (open_bins_count as f64 / 10.0);

    post + dead_space_penalty + lookahead_reward + new_bin_penalty + state_coupling
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (lower post_residual)
    let mut score = post_residual as f64;

    // Penalty for creating new bins: increase penalty as we approach the end of the stream
    // to encourage filling existing bins, but allow flexibility early on.
    if is_new_bin {
        score += 15.0 + (progress * 40.0);
    }

    // Dynamic coupling: If a bin is nearly full after placement, reward it.
    // However, if the post_residual is very small (e.g., < 5), it might be 
    // too restrictive for future items.
    if post_residual < 10 {
        score -= (10.0 - post_residual as f64) * 0.5;
    }

    // Lookahead logic: If the next item is large, avoid leaving a residual
    // that is just slightly too small to accommodate it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste_factor = (next_item_size - post_residual) as f64;
        score += waste_factor * 1.2;
    }

    // Balancing: Favor bins that keep the mean_residual of the system consistent.
    // If this bin's post_residual is significantly lower than the system mean, 
    // it helps compact the packing.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Penalty for fragmentation: If there are many open bins, penalize opening 
    // another one unless it's a very tight fit.
    if is_new_bin && open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining gaps to encourage tight packing.
    // We weight this by the current density of the bin.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, 
    // highly reward this bin. We subtract to prioritize.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_tightness = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_tightness) * 2.5;
    }

    // 3. Fragmentation Control: Avoid creating "dead zones" (gaps < 10) 
    // unless it is the last item or the gap is zero.
    if post_residual > 0 && post_residual < 10 && step_index < total_items - 1 {
        score += 40.0;
    }

    // 4. New Bin Thresholding: If this is a new bin, only pick it if forced 
    // or if the mean residual of existing bins is already very low (fragmented).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other bins can fit the item,
            // unless current bins are extremely packed.
            score += 60.0 + (mean_residual * 0.8);
        }
    } else {
        // 5. Mean Residual Alignment: Favor bins that stay close to the current
        // global mean residual to keep bin states uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

