        if open_bins_count > 0 {
            // Penalty scales with how much space is already available elsewhere.
            score += 45.0 + (mean_residual * 0.8);
        }
    }

    // 4. Scarcity/Efficiency: If this is the last fitting bin, prioritize it to avoid
    // stranding items that might not fit in remaining bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression weighting: As we near the end of the stream, prioritize 
    // filling existing bins to minimize the total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Non-linear gap penalty: Specifically target the "mid-range" waste 
    // which is harder to fill than small gaps or near-empty bins.
    if post_residual > 5 && post_residual < 20 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

