    // We want to minimize post_residual, so lower values are preferred.
    let mut score = post_residual as f64;

    // Penalty for opening new bins: 
    // We scale the penalty by progress to discourage new bins early, 
    // but allow them late when packing density matters less than completion.
    if is_new_bin {
        score += 25.0 * (1.0 - progress).exp();
        // If there are other bins that could fit the item, penalize the new bin heavily.
        if fitting_bins_count > 0 {
            score += 50.0;
