    } else {
        // Reward bins that have residuals close to the next_item_size to enable 
        // future perfect fits (Lookahead optimization).
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score += 0.5 * diff;
        }

        // Penalty for creating "slivers" (very small unusable residuals).
        // If post_residual is < 10 (smallest possible item size), it's likely dead space.
        if post_residual < 10 && post_residual > 0 {
            score += (10.0 - post_residual as f64) * 2.0;
        }
    }

    // Adjust based on the mean residual of all open bins.
    // If the current bin's residual is much higher than the mean, we prefer using it
    // to consolidate space (reducing variance).
    if !is_new_bin {
        let deviation = bin_residual as f64 - mean_residual;
        score -= 0.2 * deviation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
