    }

    // Harmonic logic: Favor residuals that are multiples of common item sizes (e.g., 20, 25, 33, 50)
    // This creates "shelves" for future items
    let harmonic_alignment = (post_residual % 25) as f64;
    score += harmonic_alignment * 0.5;

    // Lookahead logic: If next item fits in post_residual, prioritize this bin heavily
    if next_item_size > 0 && post_residual >= next_item_size {
