            if progress > 0.8 && mean_residual < 20.0 {
                score += 30.0;
            }
        }
    } else {
        // Reward filling bins that are already partially full to keep open_bins_count low
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Dampen score by mean_residual to avoid over-filling bins that are already too sparse
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
