        score -= (30.0 - diff).max(0.0);
    }

    // 4. Mean Residual Balancing:
    // Penalize bins that deviate significantly from the mean residual of the system.
    // This promotes a uniform spread of space across bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Urgency / Last Resort:
    // If this is the only bin that can fit the item, prioritize it to avoid 
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progression Scaling:
    // As we approach the end of the stream, tighten the criteria to encourage 
    // tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize near-empty bins
    // A post_residual of 0 is perfect (score 0), but we add a penalty for creating small fragments
    // if the bin is not nearly full.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Penalty for creating "slivers" that are hard to fill
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // we prioritize this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
