    // 3. Global State: If we have many open bins, we should be more aggressive in filling
    // existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalize opening a new bin if we have many bins already open or if we are late in the stream.
        score += (open_bins_count as f64 * 2.0) + (progress * 50.0);

        // If only one bin can fit the item, opening a new one is usually bad.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    } else {
        // Existing bin: Reward bins that are closer to the mean residual to keep distribution uniform
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.5;
    }

    // 4. Tightness Control: If the current item is large, prioritize bins where the
    // residual is almost exactly the item size.
    if item_size > 70 {
