pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the square of the post_residual to heavily penalize large gaps
    // (Best Fit Decreasing logic).
    let mut score = post * post;

    // Penalty for opening a new bin:
    // If bin is empty, apply a cost based on the remaining stream length.
    // As we approach the end of the stream, we become more aggressive in opening new bins
    // to avoid leaving large gaps in existing bins.
    if bin_residual == bin_capacity {
