        score += residual_impact * 5.0 * (1.0 + progress);
    }

    // Constraint handling:
    // If this is the only fitting bin, reduce its score to prioritize consolidation
    // over opening a new bin, unless the fit is extremely poor (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= (bin_capacity - post_residual) as f64;
    }

    score
