        } else {
            // Penalize opening a new bin if a decent fit exists
            score = 45.0 + (mean_residual * 0.5);
        }
    }

    // 6. Dynamic pressure: Use mean_residual to balance packing density
    // If mean_residual is high, we are under-packing; penalize larger residuals.
    score += mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead zones": if post_residual is small but > 0, it is likely wasted.
    // We penalize values between 1 and 9 heavily, as they are hard to fill.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If a future item exists, reward bins that can accommodate it.
    // If next_item_size fits in the post_residual, reduce the score to prefer this bin.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Dynamic thresholding: as we near the end of the stream, prioritize packing tightly
    // to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0; // Strong preference to use the last available fitting bin
    }

    // Penalize opening a new bin (bin_residual == bin_capacity) progressively more
    // as the stream progresses, to force consolidation.
    if bin_residual == bin_capacity {
        score += 20.0 + (30.0 * progress);
    }

    // Interaction term: balance the residual against the global mean.
    // If the bin is significantly emptier than the mean, it's a "fresh" bin; 
    // if it's tighter than the mean, it's a good candidate for consolidation.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * residual_diff * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize post_residuals that are small but non-zero (fragments)
    // We favor perfect fits (post_residual == 0) or large residuals.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // 2. Lookahead Logic: If the next item fits into the current post_residual, reward this bin.
    // This acts as a predictive Best-Fit.
    if next_item_size > 0 && post_residual >= next_item_size {
