    }

    // 3. Fragmentation Control: Avoid creating bins with residuals that are "useless"
    // (i.e., less than the smallest probable item size, here assumed ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. New Bin Thresholding: Prevent opening a new bin unless the current fit is catastrophic.
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already tight
        // or if we have very few bins open (to avoid excessive fragmentation).
        if mean_residual > 20.0 || open_bins_count < 3 {
