        }
    }

    // 5. Fitting Pressure: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Harmonic Class Bias: Prefer filling bins to specific capacity tiers (e.g., multiples of 25)
    // to keep the bin space "clean" for future items.
    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 10.0;
    } else if remainder > 20 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
