        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // 3. Mean Residual Balancing: Avoid creating bins that are significantly 
    // worse than the current average residual (prevents fragmentation).
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 4. Scarcity/Urgency: If this is the only bin that can fit the current item, 
    // prioritize it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression adjustment: As the stream nears the end, become more aggressive 
    // about filling existing space to avoid leaving trailing empty bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
