    // 3. Dynamic Thresholding: As the stream nears the end, become more aggressive 
    // about using open bins to avoid opening new ones.
    if fitting_bins_count > 0 && bin_residual < bin_capacity {
        score -= (1.0 - progress) * 15.0;
    }

    // 4. Global State Awareness: If we have many open bins, penalize opening a new one 
    // (where bin_residual == bin_capacity) to force consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 12.0;
        // Further penalize opening a new bin if we are near the end of the stream
        score += progress * 40.0;
    }

    // 5. Balance against mean_residual: If this bin's residual is significantly 
    // larger than the mean, it's a "wasteful" bin, penalize it.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

