    let post = post_residual as f64;

    // Penalize small residuals (dead space) more heavily as the stream progresses
    // to force tighter packing later in the sequence.
    let dead_space_penalty = (100.0 - post) * (1.0 + progress);

    // Reward bins that can accommodate the next item (lookahead).
    // If next_item_size is 0 (end of stream), this has no effect.
    let lookahead_reward = if next_item_size > 0 && post_residual >= next_item_size {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Calculate a dynamic threshold for opening a new bin:
    // If the current post_residual is very high (poor fit), penalize it 
    // to encourage the algorithm to prefer a new bin or a tighter fit.
    let fit_efficiency = if fitting_bins_count == 0 {
        // This is a new bin candidate
        50.0 + (mean_residual * 0.5)
    } else {
        // This is an existing bin candidate
        post + (post.powi(2) / 100.0)
    };

    let score = fit_efficiency + dead_space_penalty + lookahead_reward;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize post_residuals that are smaller than the smallest possible item (assumed 10)
