    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            // New bin is necessary, normalize cost based on item size to prefer 
            // starting new bins with larger items.
            score += 100.0 - item_size as f64;
        }
    }

    // Global state awareness: If we have many open bins, penalize opening new ones further.
    // If we have few open bins, we can be more selective.
    score += (open_bins_count as f64) * 2.0;

    // Mean residual pressure: If the average bin is nearly full, be more aggressive
    // about filling the current bin.
    if mean_residual < 20.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
