    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. New Bin Logic: If bin_residual == bin_capacity, we are evaluating a new bin.
    // We penalize opening a new bin unless the current open bins have very poor 
    // fit potential (high mean_residual).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average empty space in existing bins 
            // is significantly larger than what the new item would leave behind.
            score = mean_residual + 15.0 - (progress * 10.0);
        }
    } else {
        // If we are placing in an existing bin, penalize bins that are 
        // significantly "emptier" than the mean, as they should be reserved
        // for larger items.
        if (bin_residual as f64) > (mean_residual * 1.2) {
            score += 10.0;
        }
    }

    // 5. Last Chance Heuristic: If this is the only bin that can fit the item, 
    // we should prefer it unless the fit is extremely poor (leaving > 60 space).
    if fitting_bins_count == 1 && post_residual < 60 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating small, unusable gaps (1-9 range) as they are hard to fill.
    // We use a quadratic penalty for small residuals to discourage "fragmentation".
    let fragmentation_penalty = if post_residual < 10 && post_residual > 0 {
        (10.0 - post_res).powi(2) * 5.0
    } else {
        0.0
    };

    // Reward bins that are nearing capacity to maximize density.
    // We scale this reward by progress to become more aggressive towards the end of the stream.
    let density_reward = (100.0 - post_res) * (0.5 + 0.5 * progress);

    // Lookahead logic: if next item is large, favor bins that can still fit it.
    // If next_item_size > post_residual, this bin is "blocking" the next item.
    let lookahead_penalty = if next_item_size > 0 && next_item_size > post_residual {
        (next_item_size - post_residual) as f64 * 2.5
    } else {
        0.0
    };

    // Discourage opening a new bin prematurely unless the current fit is extremely poor.
    // If bin_residual == bin_capacity, it's a new bin.
    let new_bin_bias = if bin_residual == bin_capacity {
        // Only open new bins if we have many open bins already or if the average residual is high
        (open_bins_count as f64 * 2.0) + (mean_residual * 0.5)
    } else {
        0.0
    };

    // Calculate score: lower is better.
    // We want small post_residual (high density), but avoid fragmentation.
    let mut score = post_res + fragmentation_penalty + lookahead_penalty + new_bin_bias - density_reward;

    // Favor bins that are the "last chance" to fit an item (fitting_bins_count == 1)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

