    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that cannot fit the next item if it could have otherwise.
            score += 40.0;
        } else {
            // Reward creating a bin that perfectly accommodates the next item.
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 2. Avoid Fragmenting: If this is the only bin that fits the current item, 
    // prioritize using it over opening a new one to prevent unnecessary bin proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 3. Global Load Balancing: Prefer bins closer to the current mean residual 
    // to keep the bin distribution uniform, avoiding extreme outliers.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // 4. New Bin Thresholding: 
    // If the bin is new, apply a heavy penalty unless the current item size is very large
    // relative to the mean bin occupancy, discouraging premature bin creation.
    if bin_residual == bin_capacity {
        score += 35.0 + (mean_residual * 0.2);

        // If the item is large (e.g., > 70% capacity), opening a new bin is less penalized.
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // 5. Progression Weighting: As we approach the end of the stream, 
    // be more aggressive about filling bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals (near-perfect fits are good).
    // This emphasizes Best-Fit logic: the smaller the gap left, the better.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Logic: If next item fits in current post_residual, reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 150.0;
        // Further reward if the resulting space is very small (avoiding fragmenting)
        score -= (100.0 - (post_residual - next_item_size) as f64);
    }

    // 3. Global State: Penalize opening new bins when many are already open.
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 25.0;
        // Increase penalty for new bins as we approach the end of the stream.
        score += (step_index as f64 / total_items as f64) * 50.0;
    }

    // 4. Fitting Constraint: If this is the only bin that fits the current item, 
    // prioritize it to avoid wasting the opportunity.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 5. Mean Residual Balancing: Avoid bins that are significantly "emptier" than the average.
    // This helps keep usage density consistent across bins.
    let residual_diff = (bin_residual as f64) - mean_residual;
    if residual_diff > 0.0 {
        score += residual_diff * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a 'dead' zone that is too small for any likely future item.
    // If the post_residual is small but > 0, it's often better to leave it empty if we can.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - post / 10.0);
    }

    // Lookahead logic: if the next item fits better in this bin, prioritize this bin.
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= 15.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: as the stream progresses, become more aggressive in 
    // filling bins to minimize the total count (prevent fragmentation).
    // Penalize opening a new bin (where bin_residual == bin_capacity) as the stream nears the end.
    if bin_residual == bin_capacity {
        score += 40.0 + (30.0 * progress);
    }

    // Coupling: If we have many fitting bins, be more selective to save space for larger items.
    // If we have few fitting bins (fitting_bins_count == 1), prioritize filling the existing one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Use mean_residual to balance the load across bins.
    // If this bin's residual is significantly lower than the mean, it's a "tight" bin;
    // we want to prioritize filling it to keep the average residual high for other bins.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
