        }
    } else {
        // 4. Tightness Reward: Favor bins that become "tight" (low residual) after placement.
        // This keeps bins packed and leaves larger gaps available in other bins.
        score -= (100.0 - post_residual as f64) * 0.1;
    }

    // 5. Global Efficiency Adjustment: As we approach the end of the stream, 
