        score += 45.0 + (mean_residual * 0.5) + (open_bins_count as f64 * 2.0);
    } else {
        // 2. Best-Fit logic: Penalize large post_residuals (wasted space)
        // We prefer post_residuals that are close to 0 (perfect fit)
        score += post_residual as f64 * 0.8;

        // 3. Lookahead: If placing this item prevents a future fit, penalize.
        // If post_residual is just slightly smaller than the next item, that's a "bad" gap.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 5 {
