            score -= 25.0;
        }

        // 5. If this is the last chance to fit into an existing bin, reward it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize closing bins
    // by penalizing the creation of new bins more heavily.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
