}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating "dead zones" (small residuals that are hard to fill).
    // An ideal fit leaves 0, but a very small residual (1-9) is often worse than a larger one.
    let dead_space_penalty = if post_res > 0.0 && post_res < 10.0 {
        25.0 - post_res
    } else {
        0.0
    };

    // Lookahead logic: if the next item fits into the current post_residual, prioritize this bin.
    let lookahead_bonus = if next_item_size > 0 && (post_res >= next_item_size as f64) {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // If this is the only bin that fits, we are forced to use it.
    // Otherwise, calculate a score based on the tightness of the fit relative to the mean.
    let tightness_score = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -50.0 // Strong incentive to use the last fitting bin
    } else {
        post_res * (1.0 + 0.5 * progress)
    };

    // New bin logic: only open if the current open bins are very poorly utilized.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            0.0
        } else {
            // Discourage opening new bins unless the average residual is already quite low
            30.0 + (mean_residual * 0.5)
        }
    } else {
        0.0
    };

    tightness_score + dead_space_penalty + lookahead_bonus + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
