    let tightness_factor = (open_bins_count as f64 / (1.0 + step_index as f64).sqrt()) * 10.0;
    score += tightness_factor * progress;

    // Reward bins that are closer to the mean_residual of the system to maintain uniformity
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy barrier.
