            // Penalize if the current placement prevents a future fit
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Pressure: As the stream progresses, favor packing tighter to minimize open bins
    // This discourages having too many bins open simultaneously
    score += (open_bins_count as f64) * (1.0 + progress * 2.0);

    // If this is the only bin that can fit the item, prioritize it to avoid 
    // unnecessary new bin creation or potential overflows
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" bins (unusable space < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 2. Lookahead logic: Reward bins that can accommodate the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect or near-perfect fit for the next item is highly prioritized
            let fit_diff = (post_residual - next_item_size) as f64;
            score -= (50.0 - fit_diff).max(0.0);
        } else {
            // Penalize if this bin will definitely NOT fit the next item
            score += 15.0;
        }
    }

    // 3. Global state adaptation: Avoid opening new bins unless necessary
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if we have many open bins already or if the fit is terrible
        // Penalize the new bin creation base cost
        score += 45.0;
        if open_bins_count > 0 {
            score += (open_bins_count as f64) * 2.0;
        }
    } else {
        // Reward using existing bins to keep count low
        score -= 10.0;

        // Reward bins that bring the bin towards the global mean residual (load balancing)
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score -= residual_diff * 0.2;
    }

    // 4. Criticality check: If this is the only bin that fits the current item, prioritize it heavily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
