        }
    } else {
        // 5. Fitting Bins Penalty: If this is the only bin that fits the item, make it very attractive.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 6. Dynamic Scaling: Penalize leaving bins with very high residuals compared to the mean.
    if post_residual as f64 > mean_residual * 1.5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) that are too small for common items (e.g., < 15)
    // The penalty is stronger as we reach the end of the stream (progress -> 1.0)
    let dead_space_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post) * (1.0 + progress * 2.0)
    } else {
        0.0
    };

    // Reward bins that can accommodate the next item (lookahead)
    // If next_item_size fits in the post_residual, reduce the score
    let lookahead_bonus = if next_item_size > 0 && post >= next_item_size as f64 {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Discourage opening new bins early in the stream unless the fit is very tight
    let new_bin_penalty = if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            0.0
        } else {
            30.0 * (1.0 - progress) + (fitting_bins_count as f64 * 5.0)
        }
    } else {
        0.0
    };

    // Use mean_residual to favor bins that are already "tight" to keep others empty
    let deviation_from_mean = (post - mean_residual).abs() * 0.1;

    // Final score: prioritize small post-residuals (Best Fit) with penalties for fragmentation
    // and bonuses for lookahead compatibility.
    post + dead_space_penalty + lookahead_bonus + new_bin_penalty + deviation_from_mean
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
