        score += 25.0 + (open_bins_count as f64 * 0.5) + (step_index as f64 / total_items as f64) * 10.0;
    } else if fitting_bins_count == 1 {
        // Reward using the last available bin to prevent unnecessary proliferation.
        score -= 15.0;
