        } else if post_residual >= next_item_size {
            // This bin is perfectly shaped for the next item.
            score -= 20.0;
        }
    }

    // 4. Global Mean Balancing
    // Avoid bins that deviate significantly from the mean residual to keep bins packed evenly.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
