    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Lookahead compatibility: If the current bin can fit the next item, reduce its score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Reward tighter packing for the next item
        score += (post_residual - next_item_size) as f64 * 0.1;
    }

    // 3. Penalty for fragmentation: If the remaining space is small but > 0, 
    // it's likely "dead space" that cannot fit most items (since items are >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Harmonic class logic: Favor bins that align with common item size patterns.
    // Bins with residuals closer to the mean_residual are preferred to keep variance low.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. New Bin Logic: Discourage opening a new bin unless the current best fit is poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the current
        // fitting options are extremely inefficient (high mean_residual).
        score += 15.0; 
        if open_bins_count > 5 {
            score += (open_bins_count as f64) * 2.0;
        }
    }

    // 6. Urgency: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
