    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic constraint: discourage new bins when fitting_bins_count is high.
    if is_new_bin {
        score += 40.0 + (fitting_bins_count as f64 * 5.0) + (progress * 20.0);
    } else {
        // Encourage using bins that bring the mean_residual closer to a target of 15-20 (sweet spot).
        let current_bin_residual = bin_residual as f64;
        let diff_from_mean = (current_bin_residual - mean_residual).abs();
        score -= diff_from_mean * 0.1;
    }

    // Final scaling: favor bins that are already partially filled to minimize bin count.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic)
    // Already base score, but we penalize bins that leave tiny, unusable fragments (1..9)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class Coupling: Prioritize fills that align with common item sizes
    // If post_residual is a multiple of 25 (e.g., 0, 25, 50, 75), it's highly desirable.
    if post_residual % 25 == 0 {
        score -= 20.0;
    }

    // 3. Lookahead Logic (Next Item):
    // If the next item fits into the current bin's post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Scarcity/Density Balancing:
    // If this is the only bin that can fit the item, we must take it unless it leaves a terrible gap.
    if fitting_bins_count == 1 && post_residual > 5 {
        score -= 30.0;
    }

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize opening it based on 
    // the current fill state of existing bins.
    if bin_residual == bin_capacity {
        // Only open new if existing bins are already quite full (mean_residual < 30)
        if mean_residual > 30.0 {
            score += 60.0;
        } else {
            score += 10.0;
        }
    }

    // 6. Progression Scaling:
    // As the stream nears the end, become more aggressive about fitting into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit typical future items
    // If the post_residual is positive but smaller than the minimum expected size (10), 
    // it creates 'fragile' space that is likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary
    // If we are considering a new bin (bin_residual == bin_capacity), penalize it 
    // based on the current number of open bins and the progress of the stream.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty for opening a new bin if an existing one could fit the item
            score += 150.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no bins fit, opening a new one is mandatory; normalize the score
            score -= 20.0;
        }
    }

    // 3. Lookahead Coupling: Reward placements that leave room for the next item
    // If the next item is large, we prefer a post_residual that is either 0 or large enough
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent fit: leaves enough room for the next item
            score -= 25.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Bad fit: creates a gap that cannot accommodate the next item
            score += 15.0;
        }
    }

    // 4. Global Efficiency: Penalize high mean_residual to favor filling up existing bins
    score += (mean_residual - post_residual as f64) * 0.5;

    // 5. Stream Progression: Toward the end of the stream, prioritize aggressive packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

