        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual).
    // We add a penalty for empty space to encourage Best-Fit behavior.
    let mut score = post;

    // Penalty for creating 'orphaned' space (very small residuals that are hard to fill).
    // If post_residual is < 10, it's often wasted space.
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (1.0 - post / 10.0);
    }

    // Dynamic pressure: as the stream progresses, prioritize closing bins more aggressively.
    // Use the mean residual to penalize bins that deviate from the efficient packing average.
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * progress;

    // Lookahead: if the next item is large, penalize bins that leave too little space.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 20.0 * (1.0 - progress);
        }
