    // New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), calculate the cost of opening it.
    // Only open if the average fit quality of existing bins is worse than the 'ideal' 
    // cost of starting fresh.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins early, lower penalty as we reach the end.
        score = 40.0 + (mean_residual * 0.5) - (progress * 10.0);
    } else {
