        if next_item_size > 0 && post >= next_item_size as f64 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Final weight: penalize high open_bins_count to encourage compaction.
    score += (open_bins_count as f64).powf(1.1) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic-Residual Balancing
    // We prioritize bins that leave a post_residual that is either 0 (perfect fit)
    // or a value that is likely to accommodate the 'next_item_size'.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Harmonic Reward: Favor post_residuals that are multiples of common item sizes
    // or leave space for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact fit for next item
            score -= 25.0 * (1.0 - (post_residual as f64 - next_item_size as f64).abs() / 100.0);
        } else {
            // Penalize creating "dead zones" (unusable fragments < 10)
            if post_residual > 0 && post_residual < 10 {
