    if is_new_bin {
        // Only open a new bin if the current packing is truly inefficient
        // or if we are nearing the end of the stream
        let progress = step_index as f64 / total_items as f64;
        score += 35.0 + (progress * 15.0);

        // If we have many bins open, penalize opening another one
        score += open_bins_count as f64 * 2.0;
    } else {
        // 3. Best-Fit refinement: Reward filling bins that are already "half-full"
        // to consolidate remaining space.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // 4. Critical threshold: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
