    // We want to minimize post_residual, but avoid creating "dead zones" (e.g., 1-9 capacity)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; // Heavy penalty for creating unusable slivers
    }

    // 2. Lookahead Integration: If the next item fits in the current post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 3. Dynamic Thresholding: As the stream progresses, become more selective about opening new bins
    if is_new_bin {
