        score += 30.0 + (progress * 40.0);

        // If other bins can fit the item, penalize opening a new one heavily
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Encourage filling bins that are already below the mean residual to consolidate space
        if (bin_residual as f64) < mean_residual {
