    if post_residual > 0 && (post_residual as f64) < mean_residual {
        score += 15.0;
    }

    // 4. New Bin Thresholding: If this is an empty bin (new bin candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are "cluttered" (high mean_residual)
        // or if we have very few open bins and want to preserve space for future items.
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 40.0; 
        } else {
            score += 60.0; // Strong penalty for opening new bins prematurely
        }
    }

    // 5. Urgency: As the stream progresses, become more aggressive in packing 
    // tightly to avoid trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    // 6. Last Chance Logic: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals (near-full bins are good)
    // We want to minimize score, so we subtract from score to reward tight packing.
    // The inverse of post_residual creates a strong pressure for tight fits.
    score -= (100.0 - post_residual as f64).powf(1.5);

    // 2. Lookahead Integration: If next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Dynamic Threshold for New Bin:
    // When progress is high, we are more desperate to finish.
    // Discourage opening new bins unless the current fit is extremely poor (large post_residual).
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing bins that can hold the item
            score += 150.0 * (1.0 - progress);
        }
        // Baseline cost to open a new bin
        score += 45.0;
    }

    // 4. Global State Balancing:
    // If our mean residual is high, we have many bins with wasted space.
    // Try to fill bins that are already "worse than average" to consolidate space.
    if !is_new_bin && (bin_residual as f64) > mean_residual {
        score -= 10.0;
    }

    // 5. Scarcity Penalty:
    // If only one bin can fit this item, prioritize using it to avoid opening a new one later.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_res;

    // Penalty for leaving "dead space" (residuals < 10 are often unusable given the item range 10-80)
    // We penalize very small residuals exponentially to favor tighter fits.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_res).powf(2.0) * 2.5;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If next_item_size > post_residual, the current bin is likely "wasted" for the next step.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: as we near the end of the stream, prioritize closing bins
    // to minimize the number of active open bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is the "New Bin" candidate call.
    // We heavily penalize opening a new bin unless the existing bins are extremely poor fits.
    if bin_residual == bin_capacity {
        // New bin penalty scales with the number of open bins and remaining stream length.
        score += 45.0 + (open_bins_count as f64 * 2.0) - (progress * 10.0);
    }

    // Interaction term: penalize deviation from the mean_residual to keep bin usage uniform.
    let residual_variance = (post_res - mean_residual).abs();
    score += residual_variance * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
