    }

    // 2. Harmonic Class Logic: Prefer residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // This maximizes the probability of fitting subsequent items perfectly.
    let harmonic_penalty = if post_residual % 20 == 0 { -5.0 } else if post_residual % 25 == 0 { -3.0 } else { 0.0 };
    score += harmonic_penalty;

