    // 1. Dead space penalty: If the remaining space is too small for the smallest possible items (10),
    // it is highly likely to be wasted. We penalize post_residual values that fall in the [1, 9] range.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 20.0;
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual,
    // we heavily reward this bin to prioritize packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
    }

    // 3. Open bins pressure: If this is an existing bin, discourage opening new ones 
    // unless the fit is extremely tight (Best Fit approach).
    if bin_residual < bin_capacity {
        // Favor bins that become very full (Best Fit behavior)
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    } else {
        // Penalize opening a new bin if we have many bins already open,
        // unless fitting_bins_count is 0 (we have no choice).
        if open_bins_count > 0 {
            score += (open_bins_count as f64) * 5.0;
        }
    }

    // 4. Global balance: If this bin's residual is significantly better than the mean, 
    // reward it to keep the distribution of residuals tight.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the basic Best-Fit objective: minimize remaining space.
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin unnecessarily.
    // If we have fitting bins, penalize the new bin candidate heavily.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0;
    }

    // 2. Lookahead matching: reward post_residuals that perfectly accommodate the next item.
    // If post_residual is close to next_item_size, we create a "tight" match.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward if the next item fits perfectly or near-perfectly.
        if post_residual >= next_item_size {
            score -= (20.0 / (1.0 + diff)) * 2.0;
        } else {
            // Penalize if the next item cannot fit in this bin after the current placement.
            score += 10.0;
        }
    }

    // 3. Fragmentation control: penalize residuals that are too small to be useful (e.g., < 10).
    // If we leave a tiny sliver, it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global balance: penalize bins that deviate significantly from the mean residual.
    // This helps keep the bin pack "level" and prevents creating isolated empty bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Progression adjustment: as we approach the end, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 50.0; // Strongly discourage opening new bins late in the stream.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space (post_residual).
    // The base score is already post_residual, which favors tight fits.

    // 2. Lookahead Awareness: If the next item fits into the current post_residual, 
    // reward this bin heavily to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Fragmentation Penalty: Penalize bins that leave space too small for any 
    // likely future item (e.g., < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 50.0 * (1.0 - progress);
    }

    // 4. Global State Balancing: If we have too many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Heavily discourage opening new bins unless necessary
            score += 40.0 + (mean_residual * 0.5);
        }
    } else {
        // Encourage using existing bins that are already "half-full" to keep mean_residual balanced
        if (bin_capacity - bin_residual) > 40 {
            score -= 5.0;
        }
    }

    // 5. Urgency: As we approach the end of the stream, prioritize closing bins
    // by favoring fits that result in zero residual.
    if post_residual == 0 {
        score -= 20.0 * progress;
    }

    // 6. Last Chance Logic: If this is the only bin that can fit the item, 
    // make it extremely attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Penalize creating "dead space" (very small residuals that are hard to fill)
    // We define a "dead zone" as residuals < 10.
    let dead_space_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powf(1.5) * 5.0
    } else {
        0.0
    };

    // Reward packing tightly (Best Fit principle)
    // We use a non-linear scaling of the post_residual to favor smaller gaps.
    let tightness_score = post.powf(1.2);

    // Lookahead logic: if the next item is large and the current post_residual is small,
    // this is a poor placement.
    let lookahead_penalty = if next_item_size > 0 {
        if post < next_item_size as f64 {
            (next_item_size as f64 - post) * 2.5
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Stream progression factor: as we reach the end of the stream, 
    // we become more aggressive about filling existing bins to avoid new ones.
    let progress_factor = 1.0 - progress;
    let open_bin_penalty = (open_bins_count as f64) * progress_factor * 2.0;

    // New bin logic: If this is an empty bin (residual == capacity),
    // only choose it if the fitting_bins_count is low or the penalty for 
    // using existing bins is extremely high.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_base = if is_new_bin {
        // High base cost for new bins, scaled by how many bins are already open
        35.0 + (open_bins_count as f64 * 1.5)
    } else {
        0.0
    };

    let mut score = tightness_score + dead_space_penalty + lookahead_penalty + open_bin_penalty + new_bin_base;

    // Strongly discourage opening a new bin if an item fits elsewhere
    if is_new_bin && fitting_bins_count > 0 {
        score += 50.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize values that 
    // create "unfillable" gaps (< 10 units, as items are >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: If the next item can perfectly fit in the current post_residual, 
    // prioritize this bin. If the next item is large, avoid bins that leave too little space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= (bin_capacity - post_residual) as f64 * 0.2;
        } else if post_residual < 20 {
            // Penalize bins that leave tiny shards that cannot fit the next item
            score += 30.0;
        }
    }

    // 3. Last-Chance Logic: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 4. New Bin Thresholding: If we are considering a new bin (bin_residual == bin_capacity),
    // only choose it if the current open bins are already highly fragmented.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Increase the cost of opening a new bin based on how well items fit in existing ones
            score = 150.0 - (mean_residual * 0.5);
        }
    }

    // 5. Progression Scaling: As we approach the end of the stream, be more conservative 
    // about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

