    // If post_residual is in (0, 10), it's highly likely to become unusable (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Coupling: If the next item is large, prioritize keeping space open.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 20.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is extremely tight (Best-Fit).
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty relative to the 
    // number of bins already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0) + 15.0;
    }

    // 4. Mean Residual Balancing: Favor bins that align with the average state of current bins.
    // This maintains "uniformity" in bin fullness, which helps in packing later items.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // 5. Last Chance Logic: If this is the only bin that can fit the item, 
    // significantly reduce its cost to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progressive Tightening: As the stream nears the end, become more aggressive
    // about filling bins to reduce the total count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals too small for common items, too large to be efficient)
    // We prioritize bins that result in a post_residual that matches the next item size
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;
    }

    // 2. Penalty for opening a new bin prematurely
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless fitting_bins_count is low
    if bin_residual == bin_capacity {
        score += (100.0 - mean_residual) * 0.5;
        if fitting_bins_count > 0 {
            score += 40.0; // Strong penalty for opening a new bin when existing ones fit
        }
    }

    // 3. Reward filling bins towards the mean residual to keep bin states uniform
    // This reduces the variance of residuals, keeping more bins "flexible" for future items
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 4. Tightness constraint: Highly reward bins that result in near-zero residual (Best Fit)
    // If post_residual is very small, it's usually a good placement
    if post_residual < 10 {
