    }

    // Encourage filling bins that are already "below average" in fullness (higher residual)
    // to keep the distribution of residuals uniform.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // Late-stage optimization: As the stream concludes, prioritize closing bins
    // by packing items into the tightest possible fitting bin.
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // Critical constraint: If this is the only bin that can fit the item, 
