}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: increase as the stream progresses to favor packing 
    // into existing space, but allow flexibility early on.
    if is_new_bin {
        score += 25.0 + (progress * 50.0);
    } else {
        // Non-linear coupling: penalize small, inefficient remaining gaps (dead space).
        // If post_residual is small but > 0, it's often a "dead" gap.
        if post_residual > 0 && post_residual < 15 {
            score += 15.0 * (1.0 - progress.sqrt());
        }

        // Lookahead bias: if the next item is large, favor bins that can accommodate it.
        if next_item_size > 0 {
            let space_needed_for_next = next_item_size as f64;
            if post_residual < next_item_size {
                score += 10.0 * (1.0 - progress);
            }
        }
    }

    // Adjust for global state: if we have many open bins, penalize opening a new one 
    // and favor consolidating into existing bins with higher mean_residual.
    let density_factor = (open_bins_count as f64) / (1.0 + mean_residual);
    score += density_factor * 5.0;

    // If this is the only bin that fits, prioritize it heavily to avoid unnecessary new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large residual space left over.
    // This is the baseline "Best Fit" behavior.
    score += (post_residual as f64) * 0.5;

    // 2. Harmonic Lookahead: If next_item_size is large, avoid small post_residuals.
    // If post_residual is smaller than next_item_size, we create a "dead" bin for the next step.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 3. Fragmentation Avoidance: Penalize residuals that are too small to hold common items.
    // If post_residual is between 1 and 9, it is effectively wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Harmonic Modulo Logic: Favor residuals that align with common item sizes (e.g., multiples of 10).
    // This encourages "clean" bin states.
    score -= (post_residual % 10) as f64 * 0.8;

    // 5. Open Bin Consolidation: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. New Bin Threshold: If considering a brand new bin (residual == capacity),
    // add a high cost to discourage opening it unless no other bin fits well.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Adjust based on current load: if many bins are already open, penalize new ones more.
        score += (open_bins_count as f64) * 2.0;
    }

    // 7. Progression normalization: As the stream nears the end, become more conservative.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "unusable" gaps (dead space < 10, since min item size is 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. If this is a new bin, penalize based on current bin pressure
    if bin_residual == bin_capacity {
        // Only open new if we have too many open bins already, or if fitting bins are scarce
        score += (open_bins_count as f64 * 2.5);
        if fitting_bins_count > 0 {
            score += 40.0; // Strong penalty for opening new bin if current ones can fit
        }
    } else {
        // 3. Prioritize bins that leave residuals close to the mean to maintain uniformity
        let diff_from_mean = (post_residual as f64 - mean_residual).abs();
        score += diff_from_mean * 0.5;

        // 4. Lookahead logic: if next item is large, favor bins that can accommodate it
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0; // Reward bins that can fit the next item
            } else if post_residual > 0 && post_residual < next_item_size {
                score += 5.0; // Small penalty if we block the next item
            }
        }
    }

    // 5. Progression scaling: as we approach the end, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (progress * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for any likely future item.
    // If post_residual is small but > 0, it is often worse than 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead logic: Reward placing an item such that the post_residual
    // is as close as possible to the next_item_size (Best-Fit Lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // 3. Pressure to consolidate: If we have many open bins, penalize opening new ones.
    // The "new bin" case has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If we have fitting bins, discourage opening a new one aggressively.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 4. Global balance: If the current bin's residual is significantly lower than 
    // the mean_residual of all bins, we are creating a tighter bin than average.
    // This is generally good for density.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Progression awareness: Towards the end of the stream, prioritize 
    // emptying open bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
    // We prioritize Best-Fit (small post_residual) but penalize "fragmentation traps" 
    // where post_residual is too small to fit any future item (10).

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the residual after placement. 
    // Lower residual is generally better (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for creating "Dead Space": 
    // If we leave a tiny gap that can't fit the smallest likely item (10), 
    // we heavily penalize it unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 2.0);
    }

    // Lookahead logic: 
    // If the next item is large and won't fit in this post_residual, 
    // we penalize this bin to keep it open for something that might fit better.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Global state awareness:
    // If we have many bins open, we want to consolidate (strongly favor smaller residuals).
    // If the bin is new, we add a significant cost to avoid opening unnecessary bins.
    if is_new_bin {
        score += 25.0 + (open_bins_count as f64 * 2.0);

        // Dynamically discourage new bins as we approach the end of the stream.
        score += (progress * 40.0);
    }

    // If this is the only bin that can fit the item, we lower the cost to force 
    // the use of existing capacity rather than opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Reward bins that have residuals close to the mean, promoting balanced fill.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
