        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // Lookahead heuristic: if the next item is large, penalize small residuals
        // that would strand the next item (making it force a new bin)
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }

        // If this is the last fitting bin, prioritize it strongly to avoid opening a new one
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Non-linear coupling: penalize 'fragmentation' (small residuals) more heavily late-game
    let fragmentation_penalty = (100.0 - post_residual as f64) * progress * 0.2;
    score += fragmentation_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    score += (post_residual as f64) * 0.5;

    // 2. Harmonic Class logic: Reward placements that leave a residual 
    // divisible by common item sizes (e.g., 20, 25, 50) to facilitate future packs.
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.8;

    // 3. Lookahead synergy: If the next item fits into the current post_residual, 
    // heavily reward this bin choice to consolidate items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 4. Strategic New Bin Threshold:
    // If the bin is new (bin_residual == bin_capacity), penalize it based on 
    // how many existing bins could have fit the item. We only want to open 
    // a new bin if the current fit quality is poor across all open bins.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 40.0;
        // Dampen new bin usage as the stream progresses to avoid fragmentation
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 5. Mean residual equilibrium: 
    // Penalize choices that push the current bin's residual too far from the global mean,
    // encouraging uniform filling across the bin set.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // 6. Last-Chance awareness: 
    // If this is the only bin that fits, prioritize it strongly to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit any likely item.
    // Gaps between 1 and 9 are extremely inefficient.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Bin Pressure: If this is the only bin that fits the item (fitting_bins_count == 1), 
    // prioritize using it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
