    // 4. Global Efficiency: Penalize opening a new bin when we have many open bins already.
    // This forces the algorithm to consolidate items into existing bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;

        // Penalize opening a new bin if the item is small enough to fit in existing open bins.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 5. Mean Residual Coupling: Encourage filling bins to be closer to the global average 
    // to keep the bin usage uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We prioritize bins where the remaining space is minimal.

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, we reward this bin.
    // This creates a "perfect match" bias for the next step.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // 3. New Bin Penalty: Strongly discourage opening a new bin unless necessary.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 85.0; 
    }

    // 4. Critical Threshold Protection: If this is the only bin that fits the item,
    // we should prioritize it significantly to avoid wasting capacity elsewhere.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Efficiency: If the current bin's post_residual is significantly worse 
    // than the global mean, penalize it to force consolidation into tighter bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 6. Progression Scaling: As the stream nears completion, become more aggressive 
    // about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-placement residual (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating "dead space" (highly unusable residuals).
    // Residuals between 1 and 9 are extremely difficult to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Heuristic: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this placement to encourage packing pairs.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // If the next item fits perfectly (or near perfectly), reward even more.
        if post_residual - next_item_size < 5 {
            score -= 15.0;
        }
    }

    // Global state awareness: If we are late in the stream, be more aggressive 
    // about filling bins tightly to avoid trailing empty capacity.
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // New bin logic: Discourage opening a new bin unless the current open bins 
    // have poor residual prospects. If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of current bins is already very small 
        // (meaning we have no good space left) or if we have very few open bins.
        if open_bins_count > 0 && mean_residual > 15.0 {
            score += 30.0;
        } else {
            score += 60.0; // Strong penalty for opening a new bin prematurely
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize the "New Bin" candidate relative to the open bins count to prevent premature bin creation
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (open_bins_count as f64).powf(1.5) * 5.0
    } else {
        0.0
    };

    // Reward bins that leave very little space (Best Fit), but penalize extreme tightness 
    // that might trap small residuals (the "dead space" avoidance).
    let tightness_score = post_res.powf(1.2);

    // Lookahead influence: If the next item is large, we want to reserve space in open bins.
    // If the current bin's post_residual is smaller than the next item, we penalize it 
    // to force the current item into a bin that leaves room for the next one.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 2.0
    } else {
        0.0
    };

    // Factor in mean_residual to balance the bin load across the pack.
    // We want to avoid bins that deviate significantly from the current average residual.
    let load_balance_penalty = (post_res - mean_residual).abs() * 0.5;

    // Progression weight: As the stream nears the end, prioritize filling bins entirely
    // to minimize the tail-end waste.
    let progress_weight = 1.0 + (progress * 2.0);

    let score = (tightness_score * progress_weight) + new_bin_penalty + lookahead_penalty + load_balance_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (fragments)
    // unless they perfectly match the next item size (lookahead).
    if post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            // Reward perfect or near-perfect fit for next item
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 0.5;
        } else {
            // Penalize "dead space" that is too small for common items
            score += (20.0 / (post_residual as f64 + 1.0)) * 5.0;
        }
    }

    // 2. Bin Threshold Logic: Favor filling bins to capacity when nearing end of stream
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 3. New Bin Thresholding: Prevent opening new bins unless necessary
    // If we are evaluating a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if fitting_bins_count is low or current bins are poorly utilized
        if fitting_bins_count > 0 {
            score += 45.0; // High penalty to open new bin if others exist
        }
        if mean_residual > 30.0 {
            score -= 10.0; // Encourage using new bin if current ones are already very fragmented
        }
    }

    // 4. Harmonic Alignment: Favor bins that leave room for items in range [20, 50]
    // which are statistically common in uniform distributions.
    if post_residual >= 20 && post_residual <= 50 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
