    if post_residual >= 10 {
        score -= (100.0 - post_residual as f64) * 0.1;
    }

    // 5. Last chance mitigation: If this is the only bin that fits, heavily favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
