        score -= 25.0;
    }

    // 3. Global state awareness: Favor filling bins that are already "below average" in fullness
    // to keep the distribution of residuals uniform and avoid fragmentation.
    let fullness_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let mean_fullness = 1.0 - (mean_residual / bin_capacity as f64);
    if fullness_ratio > mean_fullness {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // 4. New bin thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if the 
    // alternative is creating a very poor fit in an existing bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        score = 45.0;
        // If there are no existing bins that fit the item, lower the cost to open one.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // As we reach the end of the stream, prioritize closing bins over opening new ones.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 30.0;
    } else {
        // 5. If this is an existing bin, reward it if it's the only one that fits.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement.
    // Lower residual is generally better (Best Fit).
    let mut score = post_res;

    // Penalty for leaving a 'sliver' (a gap too small for most items, e.g., < 10).
    // We penalize based on the post_residual value being in the range (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if next_item_size is large, favor bins that can still fit it.
    // If next_item_size is 0 (end of stream), we prioritize closing bins (lower residual).
    if next_item_size > 0 {
        let fit_next = (post_residual as u32 >= next_item_size) as i32 as f64;
        score -= fit_next * (next_item_size as f64 * 0.5);
    }

    // Dynamic weighting based on stream progress. 
    // As we near the end of the stream, prioritize packing density over future flexibility.
    let tightness_penalty = (mean_residual - post_res).abs() * progress;
    score += tightness_penalty;

    // If this is the only bin that can fit the item, reward it to prevent premature new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin (where bin_residual == bin_capacity) 
    // proportional to the number of existing bins to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want the smallest non-negative post_residual.
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Class Logic: Reward bins that leave residuals compatible with common item sizes
    // If post_residual is a multiple of 10, it's more likely to fit future items.
    if post_residual % 10 != 0 {
        score += 5.0;
    }

    // 3. Lookahead Integration: If next_item_size fits in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Reward tight fit for next_item_size
        score += (post_residual - next_item_size) as f64 * 0.5;
    }

    // 4. Scarcity Penalty: If this is the only bin that fits the current item, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // 5. New Bin Threshold: Discourage opening new bins unless the fit is truly catastrophic
    // We weight the open_bins_count to encourage packing items into existing infrastructure.
    if is_new_bin {
        score += 30.0 + (open_bins_count as f64 * 2.0);
        // If we have many open bins, opening a new one is very expensive
        score += (open_bins_count as f64).sqrt() * 10.0;
    }

    // 6. Distribution Smoothing: Use mean_residual to avoid creating bins that are significantly "emptier" 
    // than the current average, preventing fragmented bin usage.
    if !is_new_bin && (bin_residual as f64) < mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" (gaps smaller than the smallest likely item, e.g., 10)
    // If the post_residual is < 10, it's likely unusable for future arrivals.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead optimization: If the next item is large, favor bins that can accommodate it.
    // If post_residual is too small to fit the next item, add a penalty.
    if next_item_size > 0 && post_residual < next_item_size {
