    }

    // 3. Pressure management: If we are near the end of the stream, be more aggressive 
    // about filling existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * 2.0 * progress;

    // 4. Penalty for opening a new bin (bin_residual == bin_capacity)
    // Only open a new bin if the current fit is extremely inefficient (e.g., post_residual is very large)
    if bin_residual == bin_capacity {
        // High penalty to prevent opening a new bin unless existing options are terrible
        score += 65.0;

        // If we are forced to open a new bin, reduce the penalty if many bins are open
        // to avoid fragmentation, but keep it high enough to prefer packing.
        score -= (open_bins_count as f64) * 0.5;
    } else {
        // 5. Best Fit logic: Encourage tight packing
        // Lower post_residual is better, so the base score already favors this.
        // We subtract a small amount based on how many bins we are currently using
        // to keep the number of active bins consolidated.
        score -= (fitting_bins_count as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins unless absolutely necessary (high fitting_bins_count)
    if bin_residual == bin_capacity {
