pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9 range) exponentially
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        100.0 / (post_res + 1.0)
    } else {
        0.0
    };

    // Reward bins that keep the mean residual balanced relative to the remaining stream
    // As progress increases, we become more aggressive about filling bins tightly
    let balance_factor = (post_res - mean_residual).abs() * progress;

    // Lookahead: if the next item is large, favor bins that have enough space left
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // Heuristic: If it's a new bin, apply a progress-dependent cost.
    // Early in the stream, we are more permissive with new bins. 
    // Later, we penalize new bins to force consolidation.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_cost = if is_new_bin {
        (open_bins_count as f64 * 2.0) + (progress * 50.0)
    } else {
        0.0
    };

    // Combine factors:
    // We want to minimize score, so we add penalties and subtract rewards.
    // We prioritize bins that result in a small post_residual (Best Fit)
    // but modulate it by the fragmentation penalty and the lookahead.
    let mut score = post_res 
        + fragmentation_penalty 
        + balance_factor 
        + lookahead_penalty 
        + new_bin_cost;

    // If this is the only fitting bin, reduce its score to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
