    }

    // 3. New Bin Penalty: Discourage opening new bins unless necessary
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one works
            score += 85.0 + (open_bins_count as f64 * 0.5);
        } else {
            // If no existing bin fits, normalize the cost
            score = 50.0;
        }
    }

    // 4. Global distribution awareness:
    // If the current post_residual is significantly below the mean_residual of other bins,
    // it suggests we are creating a "tight" bin that might be harder to fill later.
    // If it's above, we are creating a "loose" bin.
    if (post_residual as f64) < mean_residual {
        score += 5.0;
    }

    // 5. Progression scaling:
    // Towards the end of the stream, prioritize clearing current bins (Best Fit) 
    // over preserving space for future items.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual. Smaller post-residual is usually better (Best Fit).
    let mut score = post_residual as f64;

    // 1. Penalty for opening new bins prematurely:
    // If we have fitting bins, penalize the new bin creation exponentially as we progress.
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 150.0 * (1.0 + progress);
        } else {
            // If no bins fit, new bin is mandatory; make it highly attractive.
            score = -10.0;
        }
    } else {
        // 2. Best-Fit refinement: 
        // Penalize residuals that are too small to fit any common future item (fragmentation).
        // If post_residual is < 10, it's effectively dead space.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0 * (1.0 - progress);
        }

        // 3. Lookahead Logic:
        // If the next item exists, check if it fits in the current post_residual.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Reward bins that can accommodate the next item (Lookahead optimization).
                score -= 40.0;
            } else if post_residual < next_item_size && post_residual > 0 {
                // Penalize bins that create a "gap" too small for the next item.
                score += 15.0;
            }
        }
    }

    // 4. Global State Balancing:
    // Penalize bins that deviate significantly from the mean residual of open bins.
    // This encourages filling bins evenly to keep options open.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Urgency:
    // As we approach the end of the stream, prioritize aggressive packing.
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for leaving "unusable" small gaps (fragmentation).
    // If post_residual is small but > 0, it's often a bad fit unless it's 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If current bin can't fit next_item_size, penalize it slightly to keep it for smaller items.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 15.0 * (1.0 - progress);
    }

    // Dynamic threshold: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Discourage opening new bins (bin_residual == bin_capacity) as the stream progresses.
    // As we reach the end of the stream, we become more desperate to avoid new bins.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 + progress);
    }

    // Coupling: If the mean residual is high, we are under-filling bins.
    // Penalize bins that increase the gap beyond the current mean.
    if post_res > mean_residual {
        score += (post_res - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (too small for any likely future item)
    // We define a dead zone as anything smaller than the minimum item size (10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10.0 - post_residual as f64);
    }

    // Best-Fit logic: prioritize bins where the post_residual is smallest
    // (score is already initialized to post_residual, so this is handled)

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is less than next_item_size, we penalize this bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that are perfectly or near-perfectly sized for the next item
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Harmonic/Modulo logic: Reward bins that align with common divisors of capacity (100)
    // 20, 25, 33, 50 are common divisors or near-divisors.
    if post_residual % 20 == 0 || post_residual % 25 == 0 {
        score -= 5.0;
    }

    // Heuristic for opening new bins:
    // If the bin is brand new (bin_residual == bin_capacity), it is only desirable if 
    // all other open bins result in a very poor fit (high post_residual).
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean_residual is already quite tight, 
        // to prevent fragmentation.
        if mean_residual > 20.0 {
            score += 15.0;
        } else {
            score += 40.0;
        }
    }

    // Penalty for proliferation of bins:
    // As the stream progresses, try to consolidate into fewer bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
