        // Slightly favor opening a new bin if current mean_residual is very low,
        // suggesting existing bins are already "full" and difficult to pack.
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    }

    // 4. Tightness reward: Heavily favor perfect fits.
    if post_residual == 0 {
        score -= 20.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // be less aggressive about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
