    // 2. Harmonic Class Logic: Reward placements that leave room for specific item archetypes
    // If post_residual is a multiple of common item sizes (e.g., 20, 25, 33), it is more versatile.
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty;

    // 3. Lookahead Integration: If next_item_size is large, favor larger residuals now to prevent new bin creation.
    if next_item_size > 0 {
