    if bin_residual == bin_capacity {
        // If we are considering a new bin, only do so if the mean residual of existing bins is very low
        // (i.e., they are already nearly full)
        score += mean_residual * 2.0;

        // If we have very few open bins, opening a new one is cheaper
        score -= (open_bins_count as f64 * 5.0);
    }

    // 5. Critical Thresholding: If this is the last bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
