    // 3. Global state awareness: If we are late in the stream, be more aggressive with packing (Best Fit)
    // If we are early, be more conservative (First Fit / maintain capacity)
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. New bin management: Discourage opening new bins unless the fit is excellent
    if bin_residual == bin_capacity {
        // Only open a new bin if the current item is very large or if it's the only way to avoid
        // poor utilization of existing bins
        if item_size < 50 {
            score += 40.0; 
        } else {
            score += 10.0;
        }
    }

    // 5. Balance existing bins: Avoid fragmentation by preferring bins that are already 
    // closer to the mean residual (standardizing bin utilization)
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. If this is the only bin that fits, prioritize it strongly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle).
    let mut score = post;

    // Penalty for creating a bin that is too small for the next expected item (lookahead coupling).
    // If next_item_size is large, avoid small post_residuals that would orphan the bin.
    if next_item_size > 0 {
        let gap = next_item_size as f64 - post;
        if gap > 0.0 {
