            score += gap * 1.5;
        }
    }

    // Dynamic adaptation to stream progression.
    // Early in the stream, prioritize tight packing (lower post_residual).
    // Late in the stream, favor utilizing existing bins (lower open_bins_count) to avoid new bin overhead.
    let packing_efficiency_weight = 1.0 - (progress * 0.5);
    score += post * packing_efficiency_weight;

    // If this is the only bin that fits, we are forced to use it. 
    // If it's a new bin, penalize based on current mean_residual to prevent fragmentation.
    if bin_residual == bin_capacity {
        // New bin penalty: only open if current open bins are all near-full (low mean_residual).
        score += (100.0 - mean_residual) * 0.8;
    } else {
        // Reward bins that stay closer to the global mean residual to keep distribution uniform.
        score += (post - mean_residual).abs() * 0.2;
    }

    // Penalty for leaving a bin with a residual that is very unlikely to be filled later.
    // Small residuals (< 10) are often "dead space".
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.0;
    }

    score
