    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
    }

    // 2. Harmonic Class Logic: Favor bins that leave residuals which are multiples of 25 (common factors of 100)
    // This encourages "perfect packing" patterns (e.g., 25, 50, 75 residuals).
    let harmonic_penalty = (post_residual % 25) as f64;
    score += harmonic_penalty * 1.5;

