    } else {
        // Reward bins that bring the mean residual closer to a target of 15 (a "tight" packing threshold)
        let residual_diff = (post_residual as f64 - 15.0).abs();
        score -= residual_diff * 0.2;
    }

    // 4. Density incentive: Reward bins that are getting fuller
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

