    // If post_residual is 0, it is a perfect fit.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Lookahead matching: If next_item_size fits in the post_residual, 
    // prioritize this bin to prepare for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Fragmentation Penalty: Avoid leaving small, unusable gaps (< 10).
    // If a gap is too small for any future item (min size 10), it's dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Global Density: If we have many open bins, penalize opening new ones 
    // by significantly increasing the score for empty bins.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Mean residual balance: If this bin's post_residual is significantly 
    // lower than the global mean, it's a good candidate to "level" the load.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 6. Urgency: If this is the only bin that fits, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
