    // 2. Lookahead Integration: If the next item can fit into the current post_residual,
    // we reward this placement heavily to avoid future bin fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 5.0;
        // Further reward if the post_residual becomes very small (perfect fit for next)
        if post_residual - next_item_size < 10 {
            score -= 20.0;
        }
    }

    // 3. Harmonic Class Logic: Reward placements that leave remainders which are 
    // multiples of common item sizes (e.g., 20, 25, 33).
    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 4. New Bin Constraint: If this is an empty bin (bin_residual == bin_capacity),
    // only open it if there are no good fits available (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing capacity
            score += 200.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If we must open a new bin, normalize the cost
            score = 50.0;
        }
    }

    // 5. Progression Scaling: As we approach the end of the stream, 
    // prioritize closing open bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0 * progress;
    }

    // 6. Mean Residual Balancing: Avoid bins that deviate significantly from the mean
    // to keep the filling density uniform across the bin set.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
