pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post-residual (Best Fit principle)
    // We prioritize bins that leave the least space (Best Fit)
    let mut score = post;

    // Penalty for creating 'dead space' (bins that are too small to fit future items)
    // If the post_residual is smaller than the smallest possible item (assumed 10), it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item_size is large, avoid leaving small residuals
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that cannot fit the next item if we are mid-stream
            score += (next_item_size as f64 - post) * (1.0 + progress);
        }
    }

    // New bin avoidance: 
    // If this is a new bin (bin_residual == bin_capacity), heavily penalize opening it
    // unless all other options are poor fits (large post_residuals).
    if bin_residual == bin_capacity {
        // Only open new if we don't have many fitting bins or if existing bins are very full
        score += 40.0 * (1.0 - (fitting_bins_count as f64 / (open_bins_count as f64 + 1.0)));
    }

    // Coupling with mean_residual:
    // If this bin's post_residual is significantly better than the current mean, reward it.
    if post < mean_residual {
        score -= (mean_residual - post) * 0.5;
    }

    // Dynamic scaling based on stream progress:
    // Toward the end of the stream, prioritize packing tightly to finish bins.
    score *= 1.0 + (progress * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // A lower score indicates a more desirable bin choice.

    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (empty space).
    // The base score (post_residual) already favors tight fits.

    // 2. Harmonic Class Logic: 
    // If the post_residual is small, it might be "dead space" that cannot fit future items.
    // We penalize values that are smaller than the smallest possible item (10) but greater than 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 3. Lookahead Synergy (next_item_size):
    // If the next item is large, we want to reserve space for it.
    // If post_residual is insufficient for next_item_size, we penalize the current choice.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0;
        } else {
            // Reward bins that can accommodate the next item perfectly (or nearly so).
            let slack = post_residual - next_item_size;
            score -= (100.0 / (slack as f64 + 1.0));
        }
    }

    // 4. New Bin Thresholding:
    // If the bin is new (bin_residual == bin_capacity), force a high cost unless necessary.
    // We only open a new bin if the current fit is extremely inefficient (e.g., post_residual > 40).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 45.0; 
        } else {
            score -= 10.0;
        }
    }

    // 5. Global Density Balancing:
    // If we have many open bins, penalize opening more unless the fit is very good.
    let density_penalty = (open_bins_count as f64) * 0.5;
    score += density_penalty;

    // 6. Mean Residual Correction:
    // Avoid creating bins that deviate significantly from the current average residual.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
