        if post >= next_item_size as f64 { -25.0 * (next_item_size as f64 / 100.0) } else { 15.0 }
    } else { 0.0 };

    // Dynamic thresholding: As the stream progresses, become more aggressive at closing bins
    // to keep the mean residual low.
    let efficiency_pressure = (mean_residual - post) * progress * 5.0;

    // New bin penalty: Only open a new bin if the fit in existing bins is truly disastrous.
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_base_cost = if is_new_bin {
