        score += (fitting_bins_count as f64 * 45.0) + (mean_residual * 0.5);
    } else {
        // Best-Fit variant with lookahead awareness.
        // We want to minimize post_residual (Best Fit), but penalize "fragmentation" 
        // if the post_residual is too small to fit the next expected item.
        if next_item_size > 0 && post_residual < next_item_size {
            // Penalize creating a "useless" gap that cannot fit the next item.
            score += 35.0 * (1.0 - progress);
        }

        // Favor bins that align with the global average residual to keep bin states uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Late-stage optimization: as the stream ends, be more aggressive with packing
    // to avoid leaving too many bins partially full.
    if progress > 0.85 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

