    // We add a penalty for creating "dead space" (small post_residual that is difficult to fill).
    // A post_residual < 10 is often wasted space, so we penalize it non-linearly.
    let mut score = post_residual as f64 + (100.0 / (post_residual as f64 + 1.0));

