    // by penalizing the creation of new bins heavily.
    if is_new_bin {
        score += 25.0 + (progress * 50.0);
    } else {
        // Reward bins that bring the mean residual closer to the next item size
        let deviation = (mean_residual - next_item_size as f64).abs();
        score -= deviation * 0.2;
    }

    // If this is the last chance to fit the item in an existing bin, prioritize it strongly.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Soft-cap on the number of open bins: penalize opening too many bins early on.
    score += (open_bins_count as f64).powf(1.2) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

