    // If post_residual is a multiple of a small integer, it is likely to accommodate 
    // future items of common sizes (like 20, 25, 33, 50).
    if post_residual > 0 {
        if post_residual % 20 == 0 { score -= 15.0; }
        else if post_residual % 25 == 0 { score -= 12.0; }
        else if post_residual % 10 == 0 { score -= 5.0; }
