    // all other fitting bins result in very poor residuals.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if other bins exist.
        score += 45.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward using existing bins if they are nearing capacity.
        if post_residual < 10 {
            score -= 20.0;
        }
    }

    // 5. Global Density Adjustment:
    // As the stream progresses, prioritize closing bins to reduce open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 5.0);

    score
}

