    let mut score = post * post;

    // Penalty for leaving a bin in a "near-empty" state early in the stream, 
    // but encourage tight packing as the stream approaches completion.
    // If post_residual is small but not zero, it might trap future large items.
    if post > 0.0 && post < 20.0 {
