    // 5. Global progress factor: As we near the end of the stream, 
    // become more aggressive about filling existing bins to reduce tail fragmentation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize fitting into existing bins that leave space for the next item
    // If post_residual is close to next_item_size, we reward it to minimize fragmentation
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score += diff * 0.5;

        // Penalize if we leave space that is too small for any potential future item (< 10)
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }
    }

    // 2. Discourage opening new bins unless the fit is truly poor
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low (tight packing)
        // or if we have very few bins open.
        score += (mean_residual * 0.8) + (open_bins_count as f64 * 2.0);
    } else {
        // 3. Favor bins that bring the residual closer to the global mean
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.3;

        // 4. If this is the last chance to fit into a bin (fitting_bins_count == 1),
        // heavily reward it to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // 5. Progression scaling: become more aggressive as we reach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

