}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // A new bin (bin_residual == bin_capacity) has a base score we need to calibrate carefully.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base Score: Preference for tighter fits (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead space" (very small residuals that are hard to fill).
    // If post_residual is < 10, it's likely unusable for future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
