        }
    }

    // 6. Final adjustment: Near the end of the stream, prioritize clearing current bins.
    if progress > 0.9 {
        score -= (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space after placement (Best Fit principle)
    let mut score = post;

    // Penalty for leaving small, unusable gaps (1..9) which are hard to fill
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If the next item is large, penalize leaving a small post_residual
    // that cannot accommodate the next item.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive 
    // in packing tightly to avoid stranding items at the end.
    // If we have many open bins, penalize opening new ones.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate call.
        // Penalty increases with the number of bins already open and progress.
        score += (open_bins_count as f64 * 2.0) + (progress * 20.0);

