        score += (post - mean_residual).abs() * 0.5;
    }

    // Curvature: Non-linear penalty for high residual space early in the stream
    // to encourage maximizing capacity usage before the stream ends.
    score += (post * post) / (bin_capacity as f64 * (1.1 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
