    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalty is high, but scales down if we have no good fits.
        score = 40.0 + (10.0 * (1.0 - progress)) + (open_bins_count as f64 * 0.5);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // If this bin is the only one that fits the current item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    score += post_residual as f64 * 0.5;

    // 2. Lookahead optimization (Harmonic coupling):
    // If next_item_size exists, penalize post_residual if it cannot fit the next item.
    // This creates a "tightness" bias favoring bins that can accommodate future items.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.5;
        } else {
            // Reward bins that create a "perfect" fit for the next item
            score -= (bin_capacity - (post_residual + next_item_size)) as f64 * 0.2;
        }
    }

    // 3. Prevent fragmentation:
    // If this is the only fitting bin, prioritize it to avoid forced new-bin creation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 4. New-bin thresholding:
    // Only open a new bin if the current post_residual is highly inefficient (e.g., < 10)
    // and we are not in the final stages of the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 45.0 + (progress * 15.0);
    }

    // 5. Harmonic Penalty for "Dead Zones":
    // Penalize post_residual values that are likely to remain empty (e.g., < 10) 
    // unless it is a perfect 0 fit.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 6. Mean Residual Balancing:
    // Penalize bins that deviate significantly from the global average residual
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

