    // If this is the only bin that can fit the item, give it a significant priority boost
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Mean residual balancing:
    // Avoid bins that are significantly tighter than the current average to prevent 
    // fragmenting space across too many bins.
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin:
    // If this is a new bin, we add a significant penalty to encourage filling existing ones first.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Lookahead matching:
    // If we have a next item, we want to favor bins where the post_residual is close to the next_item_size.
    // We heavily reward (subtract) bins where the post_residual is >= next_item_size,
    // and penalize bins where the post_residual is slightly smaller than next_item_size (wasted potential).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            score += (next_item_size - post_residual) as f64 * 1.5;
