    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // 5. Balance against the mean_residual to avoid "outlier" bins.
    // If this bin's post_residual is significantly worse than the mean, penalize it.
    if (post_residual as f64) > mean_residual + 10.0 {
