pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow more flexibility 
    // as the stream progresses to reduce fragmentation.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 45.0 + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Calculate "fit tightness": lower post_residual is generally better (Best Fit),
    // but we adjust based on the lookahead (next_item_size).
    // If the next item fits perfectly into this post_residual, we reward the placement.
    let lookahead_affinity = if next_item_size > 0 && next_item_size <= post_residual {
        (post_residual - next_item_size) as f64 * 0.5
    } else {
        0.0
    };

    // Penalize creating "dead space" that is too small for any likely item (e.g., < 10)
    // but also avoid leaving space that is just barely unusable for the lookahead.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        15.0 - (post_residual as f64)
    } else {
        0.0
    };

    // Interaction between current fit and the global state (mean_residual).
    // We prefer bins that keep the overall mean residual consistent.
    let deviation_penalty = (post as f64 - mean_residual).abs() * 0.2;

    // Combine factors:
    // 1. Prioritize tight fits (base post_residual).
    // 2. Add penalties for creating tiny, unusable gaps.
    // 3. Subtract rewards for accommodating the next item.
    // 4. Apply progression-based new bin control.
    let mut score = post + new_bin_penalty + dead_space_penalty + deviation_penalty - lookahead_affinity;

    // If only one bin fits, force it to have a lower score to prevent unnecessary new bin creation
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
