    // 2. Best-Fit/First-Fit Pressure: If this is the only bin that fits the current item, 
    // prioritize it strongly to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 3. Lookahead Sensitivity: If the next item is large, prioritize bins that 
    // can accommodate it, or keep bins open that are already large.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Global Density Control: As the stream progresses, penalize opening new bins 
    // unless the fit is near-perfect to maximize utilization of existing capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Base penalty for opening a new bin increases with progress
        score += 40.0 + (progress * 30.0);

        // If we have many open bins, make it very expensive to open a new one
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Mean residual alignment: Favor bins that stay close to the average state 
    // to keep the distribution of remaining spaces uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    score
