    // 2. Harmonic Class Logic:
    // If the post_residual is a multiple of a small integer, it might be a "harmonic" fit
    // for future items. If post_residual is small (e.g., < 10), it is a "dead zone".
    if post_residual < 10 && post_residual > 0 {
        score += 20.0; // Penalty for creating small, unusable slivers
    }

    // 3. Lookahead Integration:
    // If we have a next_item_size, we want the current post_residual to accommodate it.
    // If post_residual is >= next_item_size, we give a significant bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else {
            // If we can't fit the next item, penalize slightly to prefer bins that can
            score += 5.0;
        }
    }

    // 4. Thresholding for New Bin Creation:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless the mean_residual is very high (meaning current bins are nearly full).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average space in existing bins is small
            // or if we have very few fitting bins.
            score += 40.0 - (mean_residual * 0.5);
        }
    }

    // 5. Fitting constraint:
    // If this is the last chance to fit an item (fitting_bins_count == 1),
    // strongly favor this bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that are too small to fit typical future items
    // If the remaining space is between 1 and 9, it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Open Bins Pressure: Penalize opening new bins when many are already active
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).powf(1.5) * 2.0;
    }

    // 3. Lookahead Synergy: If the next item fits into the post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. Tightness Reward: Favor bins that become very full (Best Fit principle)
    // We reward post_residual values close to 0 specifically when they are not in the "dead space" zone.
    if post_residual >= 10 {
        score -= (100.0 - post_residual as f64) * 0.1;
    }

    // 5. Fitting Bottleneck: If this is the only bin that fits the current item, 
    // heavily incentivize choosing it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progressive Consolidation: As the stream nears completion, favor filling existing bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the remaining space (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin unless absolutely necessary (or if the fit is terrible).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Heavy penalty for opening a new bin if space exists.
        } else {
            score -= 50.0;  // Reward opening a new bin if we have no choice.
        }
    }

    // 2. Lookahead optimization: If the next item fits perfectly in the post_residual,
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave just enough space for the next item
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a sliver of space that cannot fit the next item
            score += 10.0;
        }
    }

    // 3. Global state balancing: Avoid creating bins with residuals significantly 
    // smaller than the average, which leads to fragmentation.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 25.0; 
    }

    // 4. Efficiency scaling: As the stream progresses, become more aggressive 
    // about filling bins tightly to avoid trailing empty bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

