    if is_new_bin {
        score += 45.0 * (1.0 - progress);
    }

    // 2. Lookahead: If the next item is large, avoid bins that leave too little space for it.
    if next_item_size > 0 && next_item_size > post_residual {
        // Penalty for creating a "dead" bin that can't fit the next item.
        score += 15.0;

        // Additional penalty if the current item leaves a gap that is useless for the next item.
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 3. Global state balance: If we have many open bins, penalize creating more.
    if is_new_bin {
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. Fitting Pressure: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 5. Residual Smoothing: Penalize deviations from the mean residual to keep bins packed evenly.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.1;

    // 6. Efficiency Adjustment: Heavily penalize leaving tiny gaps (slivers) that are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily as we reach the end of the stream
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        25.0 * (1.0 + progress.powf(2.0)) 
    } else { 
        0.0 
    };

    // Reward placements that leave little residual space, but penalize "near-empty" bins 
    // that could have been better filled by the next_item_size.
    // If post_residual is small but next_item_size is large, this is a bad fit.
    let lookahead_mismatch = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 0.5
    } else {
        0.0
    };

    // Encourage filling bins that are already closer to the mean_residual to keep pack density uniform
    let density_penalty = (post_residual as f64 - mean_residual).abs() * 0.2;

    // Favor bins that are the "last chance" to fit an item (fitting_bins_count == 1)
    let urgency_bonus = if fitting_bins_count <= 1 && !is_new_bin { -15.0 } else { 0.0 };

    // Final score: base post_residual (Best Fit principle) + non-linear penalties
    let score = post + new_bin_penalty + lookahead_mismatch + density_penalty + urgency_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

