    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: If post_residual is small, it might be unusable for future items.
    // If post_residual is in the range [1, 10], it is likely "dead space" because min item size is 1.
    // We penalize very small residuals that cannot fit the next expected item.
    if post_residual > 0 && post_residual < next_item_size {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 3. Lookahead Synergy: If the next item fits perfectly into the remaining space, 
    // favor this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = post_residual - next_item_size;
        // Reward bins that leave exactly enough space for the next item.
        if fit_margin < 10 {
            score -= 40.0 * (1.0 - (fit_margin as f64 / 10.0));
        }
    }

    // 4. Bin Consolidation: If this is the only bin that fits the item (fitting_bins_count == 1),
    // we should prioritize using it over opening a new bin, unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. New Bin Threshold: If we are considering a new bin (bin_residual == bin_capacity),
    // add a high cost to discourage opening it unless existing bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Adjust new bin cost based on how many bins are already open (prevent fragmentation).
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. Mean Residual Awareness: If the current bin's post_residual is much higher than 
    // the mean residual of other bins, penalize it to keep the "average" bin density high.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
