pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow flexibility as the stream ends.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        (1.0 - progress) * 40.0 + 15.0 
    } else { 
        0.0 
    };

    // Calculate how "tight" this fit is relative to the average bin state.
    // We want to minimize post_residual (Best Fit), but penalize creating "sliver" 
    // spaces (e.g., post_residual < 10) that are unlikely to fit future items.
    let sliver_penalty = if post > 0.0 && post < 12.0 {
        (12.0 - post) * 2.5
    } else {
        0.0
    };

    // Incorporate lookahead: if the next item is large, favor bins that leave 
    // enough space for it, or conversely, pack the current item into a bin 
    // that cannot fit the next item anyway to "save" larger gaps.
    let lookahead_mod = if next_item_size > 0 {
        if post >= next_item_size as f64 {
            -5.0 // Reward bins that can accommodate the next item
        } else {
            2.0 // Penalize bins that would be "dead" for the next item
        }
    } else {
        0.0
    };

    // Influence of current bin distribution: if we have many bins, be more aggressive
    // about packing tightly to close them out.
    let density_factor = (open_bins_count as f64).sqrt() * 0.5;

    let mut score = post + sliver_penalty + new_bin_penalty + lookahead_mod + density_factor;

    // Final normalization: if fitting_bins_count is 1, this is a forced choice, 
    // so we reduce the penalty to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // 2. Harmonic Class Logic: If post_residual is small, it might fit future items.
    // We prioritize keeping residuals that are multiples of common item sizes.
    let harmonic_penalty = if post_residual > 0 {
        (post_residual as f64 % 20.0) * 0.5
    } else {
        -10.0 // Reward perfect fits
    };
    score += harmonic_penalty;

    // 3. Lookahead Sensitivity: If the next item is large, avoid small residuals
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0; // Avoid creating a "dead" bin for the next expected item
        } else {
            score -= 5.0; // Reward creating room for the next item
        }
    }

    // 4. Scarcity Penalty: If we have many open bins, be more aggressive with packing
    score += (open_bins_count as f64) * 0.1;

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), set a threshold
    // to prevent opening new bins unless the current best fit is very poor.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high; only take if mean_residual is low
        score = 45.0 + (mean_residual * 0.5);
    } else {
        // If this is the last bin that can fit the item, prioritize it heavily
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 6. Progression adjustment
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
