    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.1;

    // 4. Prefer bins that are already "half-filled" to keep the number of active bins low.
    let current_fill = (bin_capacity - bin_residual) as f64;
    score -= current_fill * 0.05;

    // 5. New bin logic:
    // If this is a new bin (bin_residual == bin_capacity), set a threshold.
    // Only open a new bin if the best existing fit is "bad" (post_residual is very small).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if existing bins are available.
            score += 35.0;
        } else {
            // Must open a new bin.
            score = 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalty for creating small, unusable gaps (the "fragmentation" trap).
    // If post_residual is small (e.g., 1-9), it is often worse than opening a new bin
    // unless we are near the end of the stream.
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_res) * (1.0 - progress).powf(0.5) * 5.0
    } else {
        0.0
    };

    // Reward bins that align with the next item to minimize future fragmentation.
    // If next_item_size fits in the post_residual, we reward this bin.
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        -(post_res - next_item_size as f64).powf(0.8)
    } else {
        0.0
    };

    // Heuristic for opening new bins:
    // If we are at the beginning of the stream, be more conservative (avoid new bins).
    // If we are near the end, be more aggressive to clear remaining items.
    let new_bin_bias = if bin_residual == bin_capacity {
        (1.0 - progress) * 15.0 + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Coupling: Favor bins that keep the mean_residual of all bins balanced,
    // penalizing bins that deviate significantly from the current average.
    let balance_penalty = (post_res - mean_residual).abs() * 0.2;

    // Final score: lower is better.
    // We prioritize Best-Fit (post_residual) but modulate with lookahead and fragmentation heuristics.
    post_res + fragmentation_penalty + lookahead_bonus + new_bin_bias + balance_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
