                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }

        // 3. Last chance penalty: if this is the only bin that can fit, we MUST take it.
        if fitting_bins_count == 1 {
            score -= 100.0;
        }

        // 4. Entropy control: penalize creating very small, unusable fragments (1-9 range)
        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // The objective is to minimize score.
    // post_residual represents the space left in the bin. 
    // We want to minimize this to improve packing density (Best Fit logic).
    let mut score = post_residual as f64;

    // Penalty for creating a 'fragment' - a residual too small to fit typical future items.
    // If post_residual is < 10 (the minimum item size), it's essentially dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Reward deeper packing if both items fit snugly.
        if post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // Dynamic threshold: If we have many open bins, we should be more aggressive 
    // in filling existing ones rather than opening new ones.
    if bin_residual == bin_capacity {
        // This is a new bin. Penalize opening it based on current fragmentation.
        // If mean_residual is low, we have space, so opening a new bin is bad.
        score += 30.0 + (100.0 - mean_residual) * 0.5;

        // If we are near the end of the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    } else {
        // If this is the last chance for the current item (fitting_bins_count == 1),
        // we should favor it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Normalize against bin count to keep score stable as the state grows.
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
