    let mut score = post_res;

    // Penalty for creating 'dead space' (bins with very small residuals that cannot fit common items).
    // If post_residual is < 10, it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 + progress);
