        score = 45.0 + (mean_residual * 0.5) - (progress * 10.0);
    }

    // Coupling with open_bins_count: 
    // Discourage opening too many bins early in the stream.
    score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

    // Favor bins that have residuals closer to the global mean to maintain uniformity.
    let residual_diff = (post_res - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
