    // 1. Dead Space Penalty: Heavily penalize small, unusable gaps.
    // If post_residual is < 10, it is likely unusable for any incoming item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Open Bin Pressure: Penalize opening new bins when current ones are available.
    // Discourage new bins unless the current fit is very poor.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // 3. Lookahead Synergy: Reward placements that leave room for the next item.
    // If the next item can fit in the post_residual, lower the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 4. Fitting Bin Scarcity: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Distribution Equilibrium:
    // Favor bins that keep the mean residual closer to the ideal average of remaining capacity.
    let current_mean_diff = (post_residual as f64 - mean_residual).abs();
    score += current_mean_diff * 0.5;

    // 6. Final progression scaling:
    // As the stream nears the end, become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot fit common items)
    // If the post_residual is less than 10, it's likely a dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead matching
    // If the next item fits perfectly into the remaining space, prioritize this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Reward bins that maintain enough space for the next item
            score -= 15.0;
        } else {
            // Penalize bins that cannot fit the next item if they are currently open
            score += 10.0;
        }
    }

    // 3. Balance against mean_residual to prevent fragmentation
    // If this bin's post_residual is significantly worse than the average, penalize it.
    if post_residual as f64 > mean_residual + 10.0 {
        score += 20.0;
    }

    // 4. Handle the "New Bin" threshold
    // If this is an empty bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the item is large
        // and doesn't fit well into current residuals.
        if open_bins_count > 0 {
            score += 35.0 + (item_size as f64 * 0.5);
        }
    }

    // 5. Urgency factor: If this is the only fitting bin, prioritize it to avoid new bin creation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Progressive tightening: As we approach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
