    // but modulate based on the remaining capacity in the bin.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead optimization: If the next item is large, favor bins that leave 
    // enough space for it (or leave the bin empty if the current fit is poor).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else if post_residual < 20 && post_residual > 0 {
            // Penalize "sliver" space that is too small for common items
            score += 40.0;
        }
    }

    // 3. New Bin Thresholding: Dynamic penalty for opening a new bin.
    // As the stream progresses, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 35.0 + (progress * 25.0);
        score += new_bin_penalty;
    }

    // 4. Global State awareness: If we have many open bins, prioritize closing 
    // them by filling them tightly, rather than scattering items.
    if open_bins_count > 5 {
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // 5. Scarcity avoidance: If this is the only bin that fits the item, 
    // prioritize it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Mean-residual balancing: Avoid bins that are significantly 
    // "emptier" than the current average to maintain uniform bin usage.
    let residual_diff = (bin_residual as f64) - mean_residual;
    if residual_diff > 0.0 {
        score += residual_diff * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
