    let mut score = post * post * 0.01;

    // Favor opening a new bin only if the stream is in the early stages (low open_bins_count)
    // or if the current packing is statistically suboptimal compared to the mean.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with how many bins are already open 
        // and current stream progress to prevent fragmentation late in the sequence.
        score += 25.0 + (open_bins_count as f64 * (1.0 - progress));
    } else {
        // Reward placements that leave a residual capable of fitting the next item.
        // This is a lookahead heuristic.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }

        // Penalty if this is the only bin that fits the item (fitting_bins_count == 1).
        // We want to force the use of the bin if it's the last viable option.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Non-linear coupling: penalize residuals that are far from the mean_residual
        // to encourage uniform bin filling.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5;
    }

    score
}

