    // 2. Lookahead Integration: If next_item_size is large, avoid leaving a small post_residual
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize placing current item here if it blocks the next item from fitting
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward if the current placement leaves enough room for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. Global State: Use mean_residual to balance packing density.
    // If our current bin is much emptier than the average, we are "wasting" it.
    let residual_diff = (bin_residual as f64) - mean_residual;
    score += residual_diff * 0.2;

    // 4. Threshold Logic for New Bins:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to (no fitting bins) or if current bins are too tight
        if fitting_bins_count > 0 {
            // Heavy penalty for opening a new bin prematurely
            score += 150.0 * (1.0 - progress);
        } else {
            // Mandatory bin opening
            score -= 1000.0;
        }
    } else {
        // If it's an existing bin, reward if it's the last chance (fitting_bins_count == 1)
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) increasingly as the stream progresses.
    // This forces tighter packing early on and reserves new bin space for the end of the stream.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (50.0 + (progress * 150.0));

    // Reward bins where the post_residual is small (tight fit), but add a non-linear 
    // curvature to avoid creating "sliver" residuals that are too small to be useful.
    // Optimal post_residual is usually 0 or > 20 (to fit future items).
    let sliver_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post).powf(2.0) * 5.0
    } else {
        0.0
    };

    // Coupling: If we have few fitting bins, we are desperate. Lower the score for any 
    // bin that fits the item to prevent opening a new bin unnecessarily.
    let desperation_factor = if fitting_bins_count <= 1 && is_new_bin == 0.0 {
        -50.0
    } else {
        0.0
    };

    // Lookahead influence: If the next item is large, prioritize keeping the post_residual 
    // large enough to accommodate it, or keep the current bin very tight if it can't fit.
    let lookahead_mod = if next_item_size > 0 {
        let fits_next = if post >= next_item_size as f64 { 1.0 } else { 0.0 };
        (1.0 - fits_next) * 15.0
    } else {
        0.0
    };

    // Final score: Combine base residual, penalties, and lookahead.
    // Lower score is better.
    post + new_bin_penalty + sliver_penalty + desperation_factor + lookahead_mod
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Penalty for opening a new bin: If fitting_bins_count > 0, penalize the empty bin
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0;
    }

    // 3. Harmonic class awareness: 
    // Reward placements that leave a residual which is a multiple of common item sizes (e.g., 20, 25)
    // to improve packing density for future items.
    let remainder_mod = (post_residual % 20) as f64;
    score += remainder_mod * 0.5;

    // 4. Lookahead coupling: 
    // If the next item is large, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next item, we create a 'forced' new bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0;
        } else {
            // Reward bins that have just enough space for the next item to keep tight packing
            score -= (post_residual - next_item_size) as f64 * 0.1;
        }
    }

    // 5. Global density pressure:
    // As we progress through the stream, if we have many open bins, 
    // punish creating even more empty space (mean_residual influence).
    if open_bins_count > 5 {
        score += mean_residual * 0.2;
    }

    // 6. Thresholding:
    // Heavily penalize 'micro-residuals' that are unlikely to fit any future items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1..9), it creates 
    // an unusable fragment. Penalize these gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Best-Fit Bias: Encourage filling bins tightly.
    // We favor bins where the post_residual is small (but not in the 1-9 "dead" range).
    score += (post_residual as f64) * 0.5;

    // 3. Lookahead Synergy: If the next item can fit in the post_residual,
