    // 2. Lookahead Synergy: If the post_residual can fit the next item, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;

        // Additional bonus if the remaining space after next_item fits would be near zero (perfect pair)
        let secondary_post = post_residual - next_item_size;
        if secondary_post < 10 {
            score -= 15.0;
        }
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current mean_residual is very low (bins are tight)
        // or if we have very few fitting bins left.
        score += 45.0; 
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // 4. Tightness Balancing: Penalize bins that deviate significantly from the mean_residual
    // to keep bin fill levels consistent (load balancing).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 5. Progression Scaling: As we approach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: prioritize bins where the post-fit residual is small (tight fit).
    // The base score (post_residual) already favors tight fits.

    // 2. Penalty for creating "dead space": if the post_residual is small but not zero,
