        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Fitting constraints: if this is the only bin that can fit the item,
    // reduce the score to ensure we don't unnecessarily open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 6. Balance residual utilization: if the bin residual is significantly higher than
