    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow flexibility as the stream progresses
    if is_new_bin {
        score += (bin_capacity as f64) * (1.0 - progress).powf(0.5) * 1.5;
    }

    // If this is the only bin that fits, we are forced to take it; 
    // prioritize it by reducing its score.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Non-linear coupling: penalize small residuals that are likely to become "dead space"
    // based on the average size of bins currently in play.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - (post_residual as f64 / mean_residual.max(1.0)));
    }

    // Lookahead: If next_item_size is large, favor bins that leave enough room for it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 10.0 * (1.0 - progress);
        } else {
            score -= 5.0 * progress;
        }
    }

    // Bias against fragmenting too many bins if we are near the end of the stream
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Strongly penalize large remaining gaps (Best-Fit logic).
    // We add the residual to the score so smaller post_residuals are preferred.
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes.
    // If post_residual is small but not zero, it might be "dead space".
    // We penalize "sliver" gaps (1-5) as they are hard to fill later.
    if post_residual > 0 && post_residual <= 5 {
        score += 25.0;
    }

    // 3. Lookahead Synergy: If the next item fits perfectly into the post_residual, 
