    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward configurations where the next item fits perfectly (diff == 0)
        score -= (100.0 - diff) * 0.8;
    }

    // 4. New Bin Thresholding:
    // If bin_residual == bin_capacity, this is a "new bin".
    // We only open a new bin if the current open bins are "bad" (high mean_residual).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is based on the average state of existing bins.
        // If the mean_residual of existing bins is low, it's better to reuse them.
        score += mean_residual * 0.5 + (open_bins_count as f64 * 2.0);
    } else {
        // For existing bins, favor those that leave room for future items.
        // If fitting_bins_count is 1, this is the only bin that fits the current item.
        if fitting_bins_count == 1 {
            score -= 50.0; // High priority to avoid opening a new bin unnecessarily.
        }
    }

    // 5. Progress Normalization:
    // As the stream progresses, become more aggressive about filling bins (lower score).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
