    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (unusable gap between 1 and 9)
    // Slivers are high-entropy states that often force new bin creation.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Heuristic: If we are forced to pick a new bin, penalize it based on open bin count
