    // 4. Pressure: If we have many open bins, penalize opening a new one heavily.
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 5. If this is the only bin that can fit the item, reward it to prevent
    // unnecessary new bin creation (unless the fit is extremely poor).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Balance: Favor bins that stay near the mean residual to keep bins 
    // "equally" filled, preventing one bin from becoming a "dead" bin.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Small post_residuals are usually good, 
    // but extreme tightness (post_residual < 10) can be detrimental 
    // if it leaves space too small for any future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into the current post_residual,
    // we reward this placement heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Global Bin Management: Avoid opening new bins unless necessary.
    // If we are looking at a new empty bin (bin_residual == bin_capacity),
    // penalize the opening unless the current fitting options are poor.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Mean Residual Balancing: If the current bin's post_residual is significantly 
    // worse than the average bin's residual, penalize it to encourage consolidation.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    // 5. Urgency Calibration: As the stream progresses, be more conservative 
    // with new bin creation.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

