    let mut score = post_residual as f64;

    // Penalty for creating "slivers" (unusable space < 10). 
    // Small residuals are only good if they are near zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // we heavily prioritize this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Global state awareness: If we have many open bins, we should be more 
    // aggressive in filling existing ones rather than opening new ones.
    if bin_residual < bin_capacity {
        // Existing bin: discourage wasting space if we have many open bins.
        score -= (open_bins_count as f64) * 0.5;
    } else {
        // New bin candidate: Only open if we are forced or if packing efficiency is high.
        // As the stream progresses, become increasingly conservative about opening new bins.
        score += 15.0 + (progress * 30.0);

        // If there is only one bin that can fit the item, we should generally use it
        // instead of opening a new one, unless the fit is extremely poor.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Adjust based on mean_residual: If current open bins are mostly empty,
    // prioritize placing items into those to keep them from becoming "ghost" bins.
    let residual_delta = (bin_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

