    let mut score = post_residual as f64;

    // Penalty for creating a "sliver": space too small for common items (< 10)
    // is highly undesirable unless it's an exact fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead interaction: If the next item is large, avoid leaving a residual
    // that is slightly smaller than the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 40.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Dynamic pressure: If progress is late, prioritize packing tightly over opening new bins.
    if is_new_bin {
        // High penalty for opening new bins early; penalty decays as we reach the end of the stream
        score += 80.0 * (1.0 - progress).powf(1.5);

        // If we are forced to open a new bin because fitting_bins_count is 0, reduce penalty
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Reward bins that bring the mean residual closer to the next_item_size
        let deviation = (mean_residual - next_item_size as f64).abs();
        score -= 5.0 * (1.0 - (deviation / bin_capacity as f64));
    }

    // Final scaling to ensure relative stability
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining gaps (dead space)
    // We prioritize bins that leave the smallest post_residual.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Logic: If a future item exists, prioritize bins that can accommodate it.
    // If the current post_residual is smaller than the next item, we penalize it 
    // because we create an "unusable" gap for the immediate future.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 50.0;
        } else {
            // Reward bins that leave exactly enough space for the next item (synergy)
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()).sqrt();
        }
    }

    // 3. New Bin Threshold: Discourage opening a new bin unless the fit is extremely poor
    // or we are at the very start of the sequence.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty for opening a new bin if an existing one could fit the item.
            score += 150.0;
        } else {
            // If no bins fit, the new bin is mandatory; set a neutral score.
            score = 20.0;
        }
    }

    // 4. Harmonic Density: Favor bins that align with common item sizes (multiples of 20/25).
    // This helps pack items that are factors of the capacity (100).
    let harmonic_fit = (post_residual % 20) as f64;
    score += harmonic_fit * 0.5;

    // 5. Global Pressure: As we reach the end of the stream, prioritize compacting 
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

