    // 2. Open Bins Pressure: Penalize creating new bins if we have many bins open, 
    // but reward filling bins tightly when the stream is nearing completion.
    let progress = step_index as f64 / total_items as f64;
    let bin_penalty = (open_bins_count as f64) * 2.0 * (1.0 - progress);

    if bin_residual == bin_capacity {
