    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // heavily incentivize using it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Mean Residual Alignment: Avoid bins that deviate significantly from the 
    // average state of open bins to keep the "temperature" of the packing consistent.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

