}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Reward bins that become "tight" (low post_residual)
    // Penalize bins that leave small, unusable gaps (1..10)
    let gap_penalty = if post_residual < 10 && post_residual > 0 { 
        (10.0 - post) * 5.0 
    } else { 
        0.0 
    };

    // Non-linear coupling: Favor smaller post_residuals early in the stream,
    // but shift strategy as we approach the end to prioritize bin consolidation.
    let base_score = post.powf(1.5) + gap_penalty;

    // Lookahead logic: If we can fit the next item into this bin, reward that bin
    // proportionally to how much of the next item it can accommodate.
    let lookahead_reward = if next_item_size > 0 && post_residual >= next_item_size {
        -(post_residual - next_item_size) as f64 * 2.0
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless the number of currently fitting bins is very low.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 10.0) * (1.0 + progress)
    } else {
        0.0
    };

    // Interaction with mean_residual to prevent fragmentation
    let fragmentation_penalty = (post - mean_residual).abs() * 0.5;

    base_score + lookahead_reward + new_bin_penalty + fragmentation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
