    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead matching: If the next item fits into the current post_residual,
    // we drastically reduce the score to prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
        // Further reward if the post_residual becomes very small (near-perfect fill)
        if (post_residual - next_item_size) < 10 {
            score -= 20.0;
        }
    }

    // 3. Penalty for fragmentation: If the post_residual is small but not zero,
    // it creates "dead space" that is hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Global balance: If we have many open bins, we want to consolidate.
    // Discourage opening a new bin if we have plenty of open bins available.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Adaptation to mean_residual: If current bin is significantly worse than
    // the average bin, penalize it to force better packing in other bins.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 6. Urgency: As we reach the end of the stream, prioritize closing bins
    // over keeping them open.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
