        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // If this is the last fitting bin, prioritize it to avoid opening a new one,
    // unless the post_residual is extremely poor (large).
    if fitting_bins_count == 1 && !is_new_bin {
        if post_residual < 20 {
            score -= 50.0;
        }
    }

    // Apply a non-linear curvature to the post_residual to favor 'tight' fits (Best Fit)
    // while exponentially penalizing bins that leave very small, unusable slivers.
    score += (post_residual as f64).powf(1.2) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
