            if space_after_next < 0 {
                // This bin will not fit the next item; penalize slightly.
                score += 5.0 * (1.0 - progress);
            }
        }
    }

    // Apply a non-linear scaling based on the density of open bins.
    // As open_bins_count increases, we want to consolidate items into fewer bins.
    score += (open_bins_count as f64).powf(1.2) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #821: Harmonic-Residual Optimization
