    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - (post_res / next_item_size as f64));
        }
    }

    // Dynamic pressure: As the stream progresses, be more conservative about opening new bins.
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if fitting_bins_count is 0.
        // We add a progress-weighted cost to opening new bins to encourage packing existing ones.
        score += 40.0 + (30.0 * progress);

        // If we have other bins that can fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0 / (fitting_bins_count as f64 + 1.0);
        }
    } else {
        // Reward bins that keep the mean_residual high (balanced distribution).
        score -= 5.0 * (post_res / mean_residual);
    }

    // Interaction term: penalize high fragmentation as we approach the end of the stream.
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
