        let progress = step_index as f64 / total_items as f64;
        score += progress * (post_residual as f64 * 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize "sliver" waste (1-5 units)
    if post_residual > 0 && post_residual <= 5 {
        score += 45.0;
    }

    // 2. Lookahead Integration: If next item fits in the remaining space, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Global Bin Management: Avoid opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is inversely proportional to progress
        // Only open new bins if fitting_bins_count is low or wasted space is inevitable
        score += 35.0 * (1.0 - progress);

        // If we have many open bins, penalize opening another one
        score += open_bins_count as f64 * 2.0;
    } else {
        // If it's an existing bin, reward bins that align with the global mean residual
        // to keep bin utilization balanced (prevents "starving" bins)
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.5;
    }

    // 4. Critical Threshold: If this is the last chance for an item, prioritize it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Final non-linear adjustment for bin tightness
    // Heavily favor bins that approach 100% utilization (low post_residual)
    score += (post_residual as f64).powf(1.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9) which are hard to fill given the input distribution.
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 - (post_residual as f64 / 10.0))
    } else {
        0.0
    };

    // Reward bins that align with the lookahead item. If next_item_size fits, reduce score.
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64)
    } else {
