    };

    // Dynamically adjust threshold for opening new bins based on progress.
    // Late in the stream, we become more conservative about opening new bins.
    let new_bin_threshold = 20.0 + (25.0 * progress);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post_res + fragmentation_penalty + lookahead_bonus;

    if is_new_bin {
        // If this is the only bin that can fit, we are forced to take it, but penalize opening new bins.
        score = new_bin_threshold + (open_bins_count as f64 * 0.5);
    } else if fitting_bins_count == 1 {
        // If this is the last chance to fit an item in an open bin, apply a significant discount.
        score -= 10.0;
    }

    // Interaction with global state: penalize creating bins that deviate significantly from mean_residual.
    let deviation = (post_res - mean_residual).abs();
    score += 0.1 * deviation * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
