    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. New bin penalty: If this is a new bin (bin_residual == bin_capacity),
    // apply a heavy penalty unless it's the only option or the current open bins are very full.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Mean residual balancing: Penalize placing items in bins that are already 
    // significantly emptier than the average, to encourage packing into "tight" bins first.
    if (bin_residual as f64) > mean_residual + 10.0 {
        score += 15.0;
    }

    // 6. Progress factor: As we approach the end of the stream, prioritize closing bins
    // by being slightly more aggressive with fitting items into existing spaces.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize it based on how many existing bins could have taken the item.
    // We only want to open a new bin if the existing options are truly poor.
    if bin_residual == bin_capacity {
        score += 50.0 * (fitting_bins_count as f64);
        score += 20.0 * (1.0 - (step_index as f64 / total_items as f64));
    } else {
