        // 3. Penalty for creating "slivers" (very small residuals that are hard to fill).
        // If post_residual is < 10, it is likely unusable for future items.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // 4. Pressure to keep the mean residual low across all bins.
        if (post_residual as f64) > mean_residual {
            score += 5.0;
        }
    }

    // 5. Final constraint: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
