        // Penalty for creating "slivers" (very small residuals that are hard to fill).
        // A residual between 1 and 9 is often useless given the 10-80 range.
        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }

        // Reward bins that bring the mean residual closer to a target (e.g., 20).
        // This keeps bins balanced.
        let deviation = (post_residual as f64 - 20.0).abs();
        score += deviation * 0.2;
    }

    // If this is the last chance to fit an item in an existing bin,
    // strongly favor it to avoid opening a new one later.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post;

    // Penalty for creating "dead space" (very small residuals that are unlikely to fit future items)
    // We penalize residuals in the (0, 10) range, as items are >= 10.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Dynamic Lookahead Coupling:
    // If we have a next item, favor bins that can accommodate both current and next items.
    if next_item_size > 0 {
        let combined_size = item_size + next_item_size;
        if bin_residual >= combined_size {
            score -= 20.0 * (1.0 - progress);
        }
    }

    // New-Bin Thresholding:
    // When bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already very tight,
        // or if we are early in the process and want to preserve options.
        if open_bins_count > 0 {
            score += mean_residual * 0.5;
        }
        // Increase cost of opening new bins as the stream progresses to encourage consolidation.
        score += progress * 40.0;
    } else {
        // If it's the last chance (only one bin fits), prioritize it heavily to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Non-linear coupling: penalize high residual variance across the set of bins
    // by comparing the current bin's post_residual to the global mean.
    score += (post - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize values that 
    // are too small to fit common small-to-mid items (the "fragmentation" trap).
    if post_residual > 0 && post_residual < 15 {
        score += 45.0;
