    // 2. Harmonic Lookahead: If the next item fits into the current post_residual, 
    // reward this bin heavily to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Further reward if this creates a "perfect" or near-perfect residual (e.g., <= 5 remaining).
        if post_residual - next_item_size <= 5 {
            score -= 20.0;
        }
    }

    // 3. Modulo-based capacity balancing: Penalize residuals that are not multiples 
    // of common item sizes, favoring bins that maintain "round" remaining capacities.
    let residual_mod = (post_residual % 20) as f64;
    score += residual_mod * 0.5;

    // 4. Open-Bin Constraint: If this is the only bin that can fit the item, 
