    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Global Density Control: As the stream progresses, favor packing tighter 
    // to minimize the tail-end bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // 6. New-Bin Thresholding: Only open a new bin if the current best existing fit 
    // is truly abysmal (residual > 70).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && post_residual > 70 {
            score = 35.0; // Moderate cost to open a new bin
        } else {
            score = 100.0; // High cost to open new bin if existing ones are available
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

