    }

    // 3. Penalty for opening new bins prematurely:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the open_bins_count is very low or fitting_bins_count is 0.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0 / (open_bins_count as f64 + 1.0);
        }
    }

    // 4. Harmonic thresholding:
    // Penalize residuals that are small but unusable (e.g., < 10) if they 
    // don't perfectly accommodate common item patterns.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 5. Mean residual equilibrium:
    // Discourage bins that deviate significantly from the mean residual of open bins
    // to keep the packing density consistent across all bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 6. Progress factor:
    // As the stream nears completion, become more aggressive in packing
    // to minimize the need for new bins at the end of the sequence.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
