    } else {
        // Favor bins that have a residual close to the mean_residual to keep bin distribution uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 4. Scarcity Logic: If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, be more aggressive about filling.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

