    // 2. Lookahead Synergy: If post_residual is close to next_item_size, we reward it.
    // We want to minimize the delta between the hole we create and the incoming demand.
    if next_item_size > 0 {
        let delta = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += delta * 0.8;

        // If the next item fits perfectly, strongly prioritize this bin.
        if post_residual == next_item_size {
