    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many options.
        score += (fitting_bins_count as f64 * 15.0) + 10.0;

        // If the item is large, opening a new bin is less egregious than if it's small.
        score -= (item_size as f64 * 0.2);
    } else {
        // 4. Mean Residual Balancing: Avoid creating outliers. 
        // If our post_residual is much larger than the average, penalize to keep bins uniform.
        if post_residual as f64 > mean_residual {
            score += (post_residual as f64 - mean_residual) * 0.3;
        }
    }

    // 5. Progression Scaling: As the stream nears the end, be more aggressive about closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
