    if is_new_bin {
        // Penalty for opening a new bin is dynamic: increases as we progress to avoid waste,
        // but remains high to encourage filling existing bins.
        score = 45.0 + (progress * 20.0);
    } else {
        // Best Fit Decreasing logic embedded: smaller post_residual is better.
        // We penalize "fragmentation" (small remaining space that can't fit upcoming items).
        if post_residual > 0 && post_residual < 10 {
            score += 15.0; 
