}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle).
    let mut score = post;

    // Penalty for leaving a 'fragment' that is too small for most items (e.g., < 10).
    // This is non-linear: smaller post_residuals that are still > 0 are penalized heavily.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post).powf(1.5) * 2.0;
    }

    // Lookahead logic: If the next item is large, avoid leaving a residual that is too small for it.
    if next_item_size > 0 {
        if post > 0.0 && post < (next_item_size as f64) {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Adaptive thresholding: As we approach the end of the stream (progress -> 1.0),
    // become more aggressive in packing into existing bins to avoid opening new ones.
    // If fitting_bins_count is 1, it's the last chance, so we reward it heavily.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Influence of mean_residual: If current open bins are already tight (low mean_residual),
    // we prefer to keep them that way. If they are sparse, we are more willing to accept
    // slightly larger post_residuals to consolidate space.
    score += (post - mean_residual).powf(2.0) * 0.1;

    // New-bin candidate handling:
    // If bin_residual == bin_capacity, this is the "New Bin" call.
    // We penalize opening a new bin by default, but reduce this penalty 
    // as the stream progresses and we have many open bins that are nearly full.
    if bin_residual == bin_capacity {
        score += 40.0 - (progress * 10.0) + (open_bins_count as f64 * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
