    }

    // 3. Efficiency Balancing: Favor bins that align with the current mean_residual to keep
    // bin utilization uniform, preventing fragmentation.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // 4. New Bin Thresholding:
    // If we are evaluating a new empty bin (bin_residual == bin_capacity),
    // only choose it if the current open bins are all poor fits (high scores).
    if bin_residual == bin_capacity {
