    // We use a quadratic penalty to strongly discourage leaving large gaps.
    let waste_penalty = post * post / 10.0;

    // Lookahead logic: if next_item_size is large, favor bins that leave enough space for it.
    // If next_item_size is 0 (end of stream), prioritize filling the current bin completely.
    let lookahead_score = if next_item_size > 0 {
