        post * 0.5
    };

    // Encourage using bins that are already "half-full" to keep the number of open bins low,
    // but balance this against the "Best Fit" waste penalty.
    let density_score = (bin_capacity - bin_residual) as f64 * 0.1;

    new_bin_penalty + waste_penalty + lookahead_score - density_score
}

