        score += (post_res - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // We scale by a factor to ensure it remains the primary driver.
    score *= 1.0;

    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This creates "bins" of capacity that are likely to accept future items.
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // 3. Lookahead Synergy: If the next item fits into the current post_residual,
    // strongly reward this bin to avoid fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Threshold Logic: If this is the last fitting bin, avoid leaving a tiny, unusable sliver (e.g., 1-9).
    // Slivers are high-risk dead space.
    if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 5. Global State Awareness:
    // As the stream progresses, favor closing bins (lower open_bins_count).
    // New bins (bin_residual == bin_capacity) are penalized based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If we are deep into the stream, penalize opening new bins more heavily.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 6. Mean Residual Balancing:
    // Penalize placements that deviate significantly from the current average bin state.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
