    // Global state adjustment: If the mean residual is high, we are being too wasteful.
    // Tighten the criteria for new bins or poor fits.
    score += mean_residual * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space; we want to minimize this (Best Fit).
    let mut score = post;

    // Penalty for leaving "dead space" that is too small for the average item or the next lookahead item.
    // If post_residual < next_item_size, we penalize because we prevent the next item from fitting.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 2.5;
    }

    // Dynamic pressure: If the bin is a NEW bin (bin_residual == bin_capacity), 
    // we scale the cost based on the phase of the stream and the scarcity of fitting bins.
    if bin_residual == bin_capacity {
        // As the stream progresses, opening new bins becomes increasingly expensive.
        // We multiply the base capacity cost by (1.0 + progress^2).
        score = (bin_capacity as f64 * 0.8) * (1.0 + progress.powi(2));

        // If there are other bins that can fit this item, penalize opening a new bin heavily.
        if fitting_bins_count > 0 {
            score += 150.0 / (fitting_bins_count as f64 + 1.0);
        }
    } else {
        // For existing bins, reward packing towards the mean residual to keep bins uniform.
        // This helps in keeping future items more likely to fit into any available bin.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.5 * (1.0 - progress);
    }

    // Final non-linear dampening: discourage creating many open bins early on.
    score += (open_bins_count as f64).powf(1.2) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave the least space (lower post_residual).
    // The base score (post_residual) already captures this.

    // 2. Penalty for creating "dead space": If post_residual is small but not zero,
    // it likely cannot fit common items (10-80). 
    // We penalize small residuals that are below the minimum expected item size (approx 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead optimization: If the next item exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for a bin that can fit the immediate next item.
            score -= 30.0;
        } else {
            // Penalty for bins that force the next item into a new bin.
            score += 5.0;
        }
    }

    // 4. Global state awareness:
    // If we have many open bins, penalize opening a new one (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Harmonic refinement:
    // Favor bins that leave room for items that are multiples of common sizes (e.g., 25, 50).
    // This reduces fragmentation by aligning residuals with the capacity.
    let remainder = post_residual % 25;
    if remainder == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // 6. Dynamic Scaling:
    // As the stream progresses, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

