    }

    // Balance against the mean residual to keep bin utilization uniform.
    // If this bin's residual after placement is much higher than the mean, 
    // it is a "loose" bin; penalize it to force tighter packing.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
