    // We penalize larger post_residuals to encourage filling bins as much as possible.
    score += (post_residual as f64) * 0.5;

    // 2. Harmonic Lookahead: If next_item_size is large, avoid leaving a small gap that 
    // nothing can fit into. If post_residual is smaller than next_item_size, we penalize.
    if next_item_size > 0 && post_residual < next_item_size {
