    if bin_residual == bin_capacity {
        score += 35.0; 
        // If we are at the end of the stream, opening a new bin is less costly.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0;
    }

    // 5. Fitting Density: If this is the last bin that can fit the item, 
    // prioritize using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Mean Residual Balancing: If the current bin is significantly emptier than the 
