    // If bin_residual == bin_capacity (new bin), apply a non-linear penalty
    // that scales with how many items are left to process.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // As progress increases, the cost of opening a new bin increases.
        score += 40.0 + (progress * 60.0);
    }

    // 4. Mean Residual balancing: Favor bins that stay near the global mean
    // to keep the bin distribution uniform.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // 5. If this is the only bin that fits the item (fitting_bins_count == 1),
    // reduce penalty to ensure we don't unnecessarily open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: We prefer smaller post_residuals (tighter fills).
    // If post_residual is 0, we have a perfect fit, which is ideal.

    // 2. Lookahead Penalty: If the post_residual is smaller than the next item, 
    // it creates a "dead space" that cannot be filled by the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0;
    }

    // 3. Perfect Match Reward: If post_residual exactly matches the next item, 
    // we heavily prioritize this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // 4. Mean Residual Balancing: If this bin's residual is significantly larger 
    // than the current mean, we penalize it to encourage packing into tighter bins.
    if (bin_residual as f64) > mean_residual {
        score += 15.0;
    }

    // 5. New Bin Thresholding: If we are considering a new bin (bin_residual == bin_capacity),
    // we only pick it if the score is very low (relative to the difficulty of fitting 
    // in existing bins).
    if bin_residual == bin_capacity {
        // If there are no fitting bins, the new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 20.0; 
        } else {
            // Otherwise, heavily penalize opening a new bin unnecessarily.
            score += 100.0;
        }
    }

    // 6. Last Chance Logic: If this is the only fitting bin (fitting_bins_count == 1),
    // we slightly favor it to prevent unnecessary fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave the smallest residual.
    // The base score (post_residual) already captures this.

    // 2. Penalize opening new bins early unless forced.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty to opening a new bin if an existing one fits.
            // This penalty scales with how much space is left in other bins.
            score += 150.0 + (mean_residual * 2.0);
        } else {
            // If no bin fits, it's a necessary cost.
            score = 0.0;
        }
    }

    // 3. Lookahead Logic: If the next item exists, favor placements that allow
    // the next item to fit in the same bin or avoid fragmenting the space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: The next item will fit in this bin. Reward it.
            score -= 40.0;
        } else if post_residual > 0 && post_residual < 10 {
            // Bad: Creates a tiny fragment that is unlikely to be filled.
            score += 25.0;
        }
    }

    // 4. Global State awareness:
    // If we are nearing the end of the stream, prioritize compacting bins
    // even if it means slightly suboptimal individual choices.
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // 5. Dynamic penalty for creating "orphan" bins:
    // If a bin has a very small residual, it becomes hard to use.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base objective: Minimize post_residual (Best Fit)
    // We add a non-linear penalty for creating "dead space" (small residuals that are hard to fill).
    // If post_residual is < 10, it's likely a "stranded" space, penalize it heavily.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 / (post_res + 1.0)
    } else {
        0.0
    };

    // Use next_item_size to influence the score. If current fit leaves enough space for
    // the next item, reward this bin choice.
    let lookahead_reward = if next_item_size > 0 && post_residual >= next_item_size {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalize opening new bins early in the stream, but allow it if the bin is empty.
    // As progress approaches 1.0, we become more aggressive about minimizing open_bins_count.
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 * (1.0 - progress) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Couple the current bin's residual with the global mean_residual.
    // If this bin's post_residual is significantly worse than the mean, penalize it.
    let deviation_penalty = (post_res - mean_residual).powi(2) * 0.1;

    // Favor bins that are "tight" (low post_residual) but avoid forcing a new bin 
    // unless necessary or beneficial for future fit.
    let mut score = post_res + dead_space_penalty + lookahead_reward + new_bin_penalty + deviation_penalty;

    // If this is the only bin that fits, strongly prefer it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals to encourage tight packing, 
    // but modulate by Harmonic Class logic.
    // If post_residual is small but not zero, it might create "dead space" that 
    // no future item can fill. We penalize small residuals that are less than 
    // the minimum possible item size (assumed ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Coupling: If next_item_size fits in this post_residual, 
    // reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Harmonic Density: Favor bins that align with the mean_residual. 
    // This keeps the remaining space in open bins homogeneous, increasing 
    // the probability that future items fit into multiple bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 4. Thresholding: If we are in the last stages of the stream, 
    // become more aggressive about closing bins (penalize opening new ones).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: increases as we progress through the stream.
        score += 25.0 + (progress * 50.0);
    }

    // 5. Fitting Constraint: If this is the only bin that fits the item, 
    // heavily prioritize it to prevent unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Modulo Harmonic Bias: Favor bins where the post_residual is a multiple 
    // of common item sizes (e.g., 20, 25, 33) to leave "clean" space.
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the remaining space is too small to fit the smallest possible 
    // future items (typically 10-20), heavily penalize this residual.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 25.0;
    }

    // 2. Lookahead optimization: If next_item_size is known, penalize states where 
    // the current placement prevents a perfect fit for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 40.0;
        } else if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 3. Open bin pressure: Penalize opening new bins when many are already open,
    // but reward using existing bins to keep the open_bins_count low.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 5.0;
    } else {
        // Favor bins that are already partially filled to pack them tightly
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // 4. Scarcity adjustment: If this is the last bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 5. Progression scaling: As we reach the end of the stream, be more 
    // aggressive about closing gaps.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the residual space left after placement; we want to minimize this (Best-Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space that is too small for common future items.
    // If post_residual is small but > 0, it is often worse than a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
