        } else {
            // If it's the only choice, normalize the cost relative to the mean_residual
            score += mean_residual;
        }
    }

    // 4. Balance the packing density:
    // If we have many open bins, prioritize filling the ones with the lowest residuals 
    // to keep the bin count low (compaction).
    if open_bins_count > 5 {
        score += (bin_residual as f64 - mean_residual).abs() * 0.5;
