}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep space tight.
    // We prioritize bins that result in smaller post_residuals.

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward this bin.
    // We want post_residual to be >= next_item_size to fit the next item perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: The closer the post_residual is to the next item, the better.
            score -= 100.0 * (1.0 / (1.0 + (post_residual - next_item_size) as f64));
        } else {
