    // 3. Fragmentation Avoidance: Penalize bins that deviate significantly from the mean_residual.
    // Keeping residuals uniform helps maintain flexibility for future items.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 4. New Bin Thresholding:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if fitting_bins_count is low.
        // This acts as a dampener to prevent premature bin creation.
        score += (open_bins_count as f64) * 2.0;

        // If we have many bins that could fit the current item, don't open a new one.
        if fitting_bins_count > 0 {
            score += 200.0;
