        // If this is the last fitting bin, prioritize using it to avoid opening a new bin later.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 5. Progression Scaling: As we approach the end of the stream, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

