        score += 20.0 + (40.0 * progress);
    } else {
        // Reward filling existing bins to consolidate space, scaled by the mean residual density.
        score -= (mean_residual / bin_capacity as f64) * 15.0;
    }

    // 4. Scarcity Constraint: If this is the only bin that fits the current item, 
    // force it to be prioritized significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
