    }

    // 4. New Bin Thresholding: Prevent opening a new bin if an existing bin can fit the item,
    // unless the fit is extremely poor (large post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if existing options are available.
            score += 150.0;
        } else {
            // Baseline cost for opening a new bin when necessary.
            score += 50.0;
        }
    }

    // 5. Global Density Adjustment: As the stream progresses, favor packing tighter.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (mean_residual / bin_capacity as f64);

    // 6. Harmonic Modulo Bias: Penalize residuals that are poor divisors of the capacity.
    // This targets "clutter" bins that don't align with standard packing patterns.
    if post_residual % 20 != 0 && post_residual > 5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is small (1-9), it is highly likely to be wasted.
    // We penalize this heavily unless it is zero (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization: If the next item can fit in the remaining space, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open bins pressure: If we are deep into the stream, try to consolidate by penalizing new bin creation.
    // If this is a new bin (bin_residual == bin_capacity), add a penalty that grows with progress.
    if bin_residual == bin_capacity {
