    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Mean-Residual Balancing:
    // Avoid creating bins that are significantly worse than the current average.
    if post_residual as f64 > mean_residual && open_bins_count > 1 {
