    }

    // 5. New Bin Decision Logic:
    // If bin_residual == bin_capacity, we are evaluating a brand new bin.
    // Only open a new bin if the current post_residual of existing bins is consistently bad 
    // or if we are forced to (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = -100.0; // Forced to open new bin
        } else {
