            // unless the mean residual is already quite low (suggesting we are packing tightly).
            score += 60.0 + (mean_residual * 0.5);
        }
    }

    // 6. Tightness reward:
    // Reward bins that have a residual close to the mean, promoting uniform bin usage.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) more heavily as the stream progresses
    // to force tighter packing later in the sequence.
    let dead_space_penalty = (1.0 - (post / bin_capacity as f64)).powf(2.0) * (1.0 + progress * 5.0);

    // Reward bins that can accommodate the next item (lookahead)
    let lookahead_reward = if next_item_size > 0 && post_residual >= next_item_size {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalty for opening a new bin: Only take if post_residual is very close to capacity
    // or if fitting_bins_count is 0.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
