            35.0 + (progress * 20.0)
        }
    } else {
        0.0
    };

    // Interaction term between current bin health and global state
    let state_coupling = (mean_residual - post) * (open_bins_count as f64 / 10.0);

    post + dead_space_penalty + lookahead_reward + new_bin_penalty + state_coupling
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
