    // New Bin Logic: Discourage opening a new bin unless the current fit is extremely poor.
    // We penalize the 'empty bin' choice (where bin_residual == bin_capacity) 
    // proportional to the number of existing bins and stream progress.
    if bin_residual == bin_capacity {
