    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;

        // If the remaining space is very small after the next item, even better.
        let post_post_residual = post_residual - next_item_size;
        if post_post_residual < 10 {
            score -= 20.0;
        }
    }

    // 3. Mean Residual Balancing: Avoid creating bins that deviate significantly
    // from the average fullness of existing bins to maintain uniform bin states.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 4. New Bin Thresholding: If this is an empty bin (new), penalize it based on 
    // the number of existing open bins to prevent unnecessary fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // If we have many fitting bins, opening a new one is highly discouraged.
        score += (fitting_bins_count as f64) * 10.0;
    } else {
        // If this is an existing bin and it's the last one that fits, prioritize it
        // to avoid opening a new bin prematurely.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive
    // about closing bins by penalizing large post-residuals even more heavily.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // The base score is already post_residual, so we adjust based on context.

    // 2. Lookahead mechanism: If next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we effectively "kill" a future fit opportunity.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 3. Global state: Penalize opening a new bin if we have plenty of open bins
    // that are already under-utilized.
    if bin_residual == bin_capacity {
        // This is a new bin. Penalize based on how many bins are already open.
        // We only want to open a new bin if the mean_residual is too high (fragmentation).
        score += (open_bins_count as f64 * 5.0) + (mean_residual * 0.5);
    } else {
        // 4. Fitting Pressure: If this is the only bin that fits, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // 5. Dynamic Time Horizon: As we reach the end of the stream, 
        // tighten the tolerance for wasted space.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // 6. Avoid "Dead Space" creation: Penalize post_residuals that are too small to
    // fit the smallest expected items (roughly 10) but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score: prioritize smaller post-residual (Best Fit logic)
    let mut score = post;

    // Penalty for leaving "dead space" that is too small for any future item
    // As the stream progresses, we become more risk-averse about creating unusable slivers
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + progress * 5.0);
    }

    // If this is a new bin (bin_residual == capacity), penalize it based on how many 
    // existing bins could have fit the item. We only want to open a new bin if 
    // the existing ones are "bad" fits (high post_residual).
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Lookahead interaction: if the next item is large, favor bins that leave 
    // enough space for it, or conversely, pack current item into the tightest fit
    // to keep larger bins open for the next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next && post > 0.0 {
            // Penalty for creating a bin that cannot accommodate the next item
            score += (next - post) * 0.5;
        }
    }

    // Pressure normalization: as the stream reaches the end, prioritize closing bins
    // by heavily penalizing bins that remain open with high residuals.
    if progress > 0.8 {
        score += (mean_residual / capacity) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Favor bins that result in post-residuals that are multiples of common item sizes (alignment).
    // Penalize small slivers (1-5) that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 6 {
        score += 25.0;
    }

    // 2. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Fitting Pressure: If this is the only bin that can fit the current item, prioritize it to avoid new bin overhead.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 4. New Bin Thresholding: If considering a new bin, penalize it relative to the average state of existing bins.
    // This prevents creating a new bin unless the current available bins are too tight to fit the item well.
    if bin_residual == bin_capacity {
        score += 35.0; // Base cost of opening a new bin
        if open_bins_count > 0 {
            score += (mean_residual * 0.5);
        }
    }

    // 5. Harmonic Class dampening: Use modulo to find "clean" fits.
    // Bins that leave a remainder that is a factor of the capacity are often better for packing.
    let harmonic_fit = (post_residual % 10) as f64;
    score += harmonic_fit * 0.5;

    // 6. Progression Scaling: As the stream nears the end, become more aggressive in packing to minimize final bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit common items 
    // but large enough to waste capacity. If post_residual is in (0, 10), it's highly likely to be dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
