        // Reward filling bins that are already "tight" to keep the number of active bins low.
        // If fitting_bins_count is 1, this is the last chance to place in an existing bin.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 4. Progress-based refinement: As the stream progresses, favor tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
