}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the score.
    // post_residual represents the remaining space. Small post_residual is generally good (Best Fit).
    // However, we want to avoid "fragile" bins that have very small, unusable remainders.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating "dead space": remainders between 1 and 9 are often hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: If the next item can fit in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // fitting bins exist. If many bins fit, opening a new one is inefficient.
    if bin_residual == bin_capacity {
        score += 35.0 + (fitting_bins_count as f64 * 15.0);
    }

    // Global state adjustment: If the mean residual of existing bins is high, 
    // try to pack into those bins rather than opening new ones or using tight bins.
    if mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // If this is the only bin that can fit the item, give it a significant boost to ensure it's picked.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Favor bins that are already partially full to consolidate space.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
