pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones": gaps smaller than the smallest likely item (e.g., < 10).
    // If post_residual is in (0, 10), it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Prioritize filling bins that are already "tight" to keep open_bins_count low.
    // If post_residual is very small (near 0), it's a "perfect fit".
    if post_residual == 0 {
        score -= 20.0;
    }

    // 3. Lookahead logic: if next_item_size fits in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 4. Pressure: If we are near the end of the stream, discourage opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is higher as progress increases (avoid fragmentation).
        score += 40.0 + (progress * 60.0);
    } else {
        // Reward using existing bins more strongly as the stream nears completion.
        score -= (progress * 15.0);
    }

    // 5. Global state: If many bins are open, penalize the creation of new ones.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 6. If this is the last chance for the current item (fitting_bins_count == 1), 
    // it's usually better to use it than to open a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for opening a new bin:
    // We heavily penalize the empty bin candidate to force Best-Fit behavior 
    // unless the fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // 2. Penalty for creating "dead space":
    // If the post_residual is smaller than the smallest likely item (10), 
    // it effectively becomes permanent waste.
    if post_residual < 10 {
        score += 25.0;
