    // 3. Lookahead Matching (The "Tight-Fit" Priority):
    // If the next item fits perfectly into the remaining space, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (10.0 / (1.0 + diff));
    }

    // 4. Mean Residual Balancing:
    // Penalize bins that deviate significantly from the mean residual of the set.
    // This promotes uniform fill levels across open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // 5. Urgency factor:
    // If this is the only bin that can fit the current item, prioritize it 
    // to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progress-based scaling:
    // As the stream nears completion, become more aggressive about filling 
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
