    // If this is a new bin, penalize it relative to the progress of the stream.
    // Near the end of the stream, be more conservative about opening new bins.
    if bin_residual == bin_capacity {
        score += 15.0 + (progress * 40.0);
    }

    // 4. Global State Balancing:
    // If we have many open bins, penalize opening a new one or choosing a bin
    // that significantly deviates from the current mean residual.
    if open_bins_count > 0 {
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Last Chance Logic:
    // If this is the only bin that can fit the item, we are forced to pick it.
    // Reduce score to ensure we don't prefer a new bin over the last fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Prefer bins that are already partially filled over empty ones
    // to consolidate and minimize active bin count.
    if bin_residual < bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;

    // Penalize creating small, unusable gaps (1..10) as they are hard to fill later.
    // However, reward small gaps if we are near the end of the stream.
    let gap_penalty = if post_residual > 0 && post_residual < 10 {
        20.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Reward bins that keep the residual close to the mean_residual of other bins (balancing).
    let balance_score = (post - mean_residual).abs() * 0.5;

    // Lookahead: If next_item_size is large, avoid leaving a small post_residual that can't fit it.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless fitting_bins_count is 0 (no other choice).
    let new_bin_penalty = if bin_residual == bin_capacity && fitting_bins_count > 0 {
        40.0 * (1.0 - progress * 0.5) 
    } else {
        0.0
    };

    // Combine: Lower score is better.
    // We favor smaller post_residual (Best Fit) modified by the penalties.
    let mut score = post + gap_penalty + balance_score + lookahead_penalty + new_bin_penalty;

    // Final normalization factor to discourage opening too many bins early on.
    score += (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
