    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;
    }

    // 3. Last Chance Logic: If this is the only bin that fits the current item, 
    //    heavily reward it to prevent opening an unnecessary new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 4. New Bin Constraint: If this is an empty bin (new bin candidate),
    //    only select it if the mean_residual is already very low, 
    //    indicating that existing bins are too tight to accommodate future items.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 40.0;
        } else {
            score += 90.0; // Strong penalty against opening new bins unless necessary
        }
    }

    // 5. Progression Adjustment: As the stream nears completion, become more aggressive
    //    in filling existing bins to prevent leftover items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-placement residual. 
    // We want to minimize this to keep bins tight (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we are forced to (no other options)
        // or if our current open bins are already very full.
        if fitting_bins_count > 0 {
            score += 45.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0;
        }
    } else {
        // Reward fitting into bins that are already tight.
        // If post_residual is very small (near 0), it's a perfect fit.
        // We penalize larger post_residuals to discourage "gaps".
        score += (post_residual as f64).powf(1.2);

        // Lookahead heuristic:
        // If the next item is large, favor keeping space open.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // This placement effectively blocks the next item from this bin.
                score += 15.0 * (1.0 - progress);
            } else {
                // This placement leaves room for the next item.
                score -= 10.0 * (1.0 - progress);
            }
        }
    }

    // Global state adjustment: 
    // Discourage creating too many fragmented bins late in the stream.
    if open_bins_count > 5 && post_residual > 20 {
        score += (open_bins_count as f64) * progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) using an exponential decay term
    // to discourage creating "dead space" that is too small for future items.
    let fragmentation_penalty = if post < 20.0 { 
        (20.0 - post).powf(1.5) * 5.0 
    } else { 
        0.0 
    };

    // Lookahead logic: if next_item_size is large, prefer bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize this bin.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size as f64 - post as f64).sqrt() * 10.0
    } else {
        0.0
    };

    // Global density management:
    // As the stream progresses, we become more conservative about opening new bins.
    // If bin_residual == bin_capacity (New Bin Candidate), penalize it more as we near the end.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (50.0 * progress) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Primary score:
    // We want to minimize post_residual (Best Fit principle),
    // but modulate it by the fragmentation and lookahead risks.
    let mut score = post + fragmentation_penalty + lookahead_penalty + new_bin_penalty;

    // Favor bins that have residuals close to the mean to maintain uniform bin usage,
    // reducing the chance of having one extremely fragmented bin.
    let variance_penalty = (post - mean_residual).abs() * 0.5;
    score += variance_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Harmonic/Modulo logic focusing on Best-Fit Decreasing tendencies 
