    // If we are considering a new bin (bin_residual == bin_capacity), 
    // we only pick it if the score is very low (i.e., we are desperate).
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is already very small,
        // suggesting that current bins are too fragmented to be useful.
        score += 40.0;
        score += mean_residual * 0.5;
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, prioritize closing bins (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
