    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // We aim for post_residual closer to 0 (tighter fit)

    // 2. Lookahead logic: If a bin can fit the next item, reward it.
    // Specifically, if post_residual >= next_item_size, we create a "synergy" bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Harmonic class awareness: 
    // Penalize residuals that are small but non-zero (fragments < 10)
    // as these are often "dead space" that cannot fit any item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. New bin thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // based on how many other bins could have taken the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if the current fit options are truly terrible
            score += 40.0 + (fitting_bins_count as f64 * 5.0);
        } else {
            // No choice, must open new bin
            score = 0.0;
        }
    }

    // 5. Global state normalization:
    // As the stream progresses, favor packing tighter to minimize the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Mean residual feedback:
    // If this bin is already emptier than average, penalize it to encourage
    // filling up existing "fuller" bins first (load balancing for better packing).
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "dead space": post_residuals that are too small to fit typical future items (10-20 range).
    // If post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 3. Pressure to consolidate: If there are many open bins, penalize opening a new bin (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If we have other options, discourage opening a new bin heavily.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Balance strategy: Favor bins that stay close to the mean_residual to keep bin states uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Progression scaling: As we approach the end of the stream, prioritize closing bins over packing efficiency.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.9 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for any likely future item (under 10).
    // If post_residual < 10, it's likely wasted space unless it's 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead matching: If the remaining space is close to the next item, prioritize this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly.
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.5;
        } else {
            // Penalize bins that block the next item from being placed in this specific bin.
            score += 20.0;
        }
    }

    // 3. Prevent opening new bins unless necessary (Best Fit strategy).
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low (bins are full).
        // Or if there are no fitting bins available.
        if fitting_bins_count > 0 {
            score += 40.0; 
        } else {
            score -= 10.0;
        }
    }

    // 4. Balance the packing density:
    // If we have many open bins, prioritize filling the ones with the lowest residuals (tightest packing).
    if open_bins_count > 5 {
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    // 5. Progression scaling: As we reach the end, be more aggressive with space usage.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
