pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the square of the post_residual to heavily penalize large gaps (Best-Fit principle).
    let mut score = post * post;

    // Penalty for opening a new bin if we are not at the very end of the stream.
    // If bin_residual == bin_capacity, this is a candidate for a new bin.
    if bin_residual == bin_capacity {
        // High cost to open a new bin early on, decaying as the stream progresses.
        score += (bin_capacity as f64).powi(2) * (1.5 - progress);
    }

    // Lookahead logic: if the next item exists, penalize configurations that make it impossible
    // to fit the next item into the current bin if it's the only one left.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size as f64 - post) * 10.0;
    }

    // Favor bins that align with the global mean residual to keep bin levels balanced.
    let mean_diff = (post - mean_residual).abs();
    score += mean_diff * 5.0;

    // If this is the last fitting bin, reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= (bin_capacity as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1211: Harmonic residual minimization with lookahead-coupling.
    // Goal: Minimize post_residual while punishing "fragile" residuals that cannot fit common future items.

    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but unusable (1..9).
    // These are "dead zones" since minimum item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Coupling: If next_item_size is large, prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // High reward for keeping the bin capable of fitting the next item.
            score -= 25.0;
        } else if post_residual > 0 {
            // Penalty for creating a bin that is too small for the next item, 
            // forcing a new bin creation later.
            score += 15.0;
        }
    }

    // 3. Density Balancing: If we have many open bins, prioritize filling the tightest one (Best Fit).
    // If we have very few, prioritize keeping more space open (First Fit).
    let density_factor = (open_bins_count as f64) / (1.0 + mean_residual);
    score += density_factor * 2.0;

    // 4. New Bin Logic: Only open a new bin if the current best existing fit is extremely poor.
    if bin_residual == bin_capacity {
        // Only consider a new bin if it's the only option or if existing bins have high residuals.
        if fitting_bins_count > 0 {
            score += 45.0; // Strong penalty to prefer existing bins.
        } else {
            score -= 10.0; // Forced opening.
        }
    }

    // 5. Harmonic Class weight: Favor residuals that are multiples of common item sizes (e.g., 20, 25).
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
