pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post-placement residual. 
    // We want to minimize this (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but not zero, 
    // it's often unusable for future items. We apply a non-linear penalty.
    if post_res > 0.0 && post_res < 15.0 {
        score += 25.0 * (1.0 - (post_res / 15.0).powf(0.5));
    }

    // Lookahead coupling: If the next item is large, we want to prioritize 
    // keeping larger residuals available in existing bins.
    if next_item_size > 0 {
        let lookahead_pressure = (next_item_size as f64 / bin_capacity as f64).powf(2.0);
        score += lookahead_pressure * (bin_capacity as f64 - post_res);
    }

    // Stream progression: As we near the end of the stream, prioritize 
    // exhausting existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Penalize opening new bins more heavily as we approach the end.
        score += 40.0 * (1.0 + progress.powf(2.0));

        // If there are other bins that could fit this item, make the new bin 
        // significantly less attractive.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // For existing bins, reward packing that brings the bin closer to 
        // the mean residual of the set to maintain uniformity.
        let deviation = (post_res - mean_residual).abs();
        score -= 5.0 * (1.0 - progress) * (1.0 / (1.0 + deviation));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
