    // We penalize opening a new bin heavily unless fitting_bins_count is low or 
    // the current item is very large (e.g., > 70).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing options
            score += 60.0 + (item_size as f64 * 0.5);
        } else {
            // If no bins fit, score is just the capacity (base cost)
            score = 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating "dead space" (very small residuals that are hard to fill later)
    // We target a residual of 0 or > 20 (size of smallest possible item)
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 - (post_res / 10.0))
    } else {
        0.0
    };

    // Reward bins that maintain a residual close to the mean_residual of existing bins
    // This encourages "leveling" the load across open bins
    let leveling_reward = (post_res - mean_residual).abs() * 0.5;

    // Lookahead: If next_item_size is large, prioritize keeping space open
    // If post_residual is too small to fit the next item, penalize
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // New bin bias: Increase penalty for opening a new bin as the stream progresses
    // to force consolidation in later stages.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        40.0 + (progress * 60.0) 
    } else {
        0.0
    };

    // Final score: Lower is better.
    // Base score is the post_residual (Best Fit principle).
    post_res + dead_space_penalty + leveling_reward + lookahead_penalty + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We target residuals that are either 0 (perfect fit) or >= 20 (likely to fit another small item).
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 - (post_residual as f64 * 2.0);
    }

    // Lookahead logic: if the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // Harmonic/Modulo logic: prioritize bins that align with the capacity to leave "clean" remainders.
    // This reduces fragmentation by encouraging bins to fill to specific thresholds.
    let harmonic_fit = (bin_capacity - post_residual) % 25;
    score += harmonic_fit as f64 * 0.5;

    // Avoid opening a new bin if we have viable alternatives.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if existing bins have space.
            score += 150.0;
        } else {
            // If no bins fit, we must open one, but we normalize the cost.
            score -= 20.0;
        }
    }

    // Global state awareness: if we are late in the stream, favor tighter packing (lower residual).
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0) * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins that are already closer to the mean residual to keep bin states balanced.
    let imbalance = (post_residual as f64 - mean_residual).abs();
    score += imbalance * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
