    // We apply a non-linear penalty for fragmentation (low post_residual values that are unusable).
    // If post_residual is < 10 (the minimum item size), it is "dead space" unless it is 0.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        100.0 / (post + 1.0)
    } else {
        0.0
    };

    // Lookahead coupling: If next_item_size is large and fits in current post_residual, 
    // prioritize preserving space. If next_item_size is large and does not fit,
    // we want to pack the current item as tightly as possible to avoid opening a new bin later.
    let lookahead_pressure = if next_item_size > 0 {
        if post_residual >= next_item_size {
            -15.0 * (next_item_size as f64 / 100.0) 
        } else {
            10.0 * (next_item_size as f64 / 100.0)
        }
    } else {
        0.0
    };

    // Dynamic thresholding: As the stream progresses, increase the cost of opening new bins
    // by penalizing the "new bin" case (bin_residual == bin_capacity).
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Efficiency bias: Favor bins that align with the current mean_residual to keep
