    // We penalize this based on the number of bins already open and the progress of the stream.
    if bin_residual == bin_capacity {
        // Only consider a new bin if we have few fitting options or if we are late in the stream
        // and need to conserve space.
        score += (fitting_bins_count as f64 * 5.0) + (open_bins_count as f64 * 2.0 * (1.0 - progress));
    } else {
        // Interaction: If fitting_bins_count is 1, this is the last chance for this item.
        // We lower the score significantly to prioritize taking this spot.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Lookahead: If the next item exists, try to leave a residual that fits it.
        if next_item_size > 0 {
            let diff = (post as f64 - next_item_size as f64).abs();
            // If the post_residual is slightly larger than the next item, it's a good fit.
            // If post_residual is smaller, it's a bad fit (penalty).
            if post < next_item_size as f64 {
                score += 40.0;
            } else {
                score += diff * 0.5;
            }
        }
    }

    // Adjust based on mean_residual: If current bin is way above average, it's a "wasteful" bin.
    // Penalize placing items in bins that are already performing worse than the global average.
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual).max(0.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead zones' (small residuals that are unlikely to fit future items)
    // We target residuals that are smaller than the smallest likely item (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if next_item_size fits in the post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // Harmonic class logic: favor placements that leave residuals which are multiples of common item sizes
    // or maximize the bin usage relative to the bin_capacity
    let usage_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= usage_ratio * 20.0;

    // Managing the 'New Bin' threshold:
    // If bin_residual == bin_capacity (New Bin Candidate), apply a dynamic threshold
    // based on how many bins are currently open and the progress of the stream.
    if bin_residual == bin_capacity {
