    // 4. Tightness bias
    // Prefer bins that become very tight (Best Fit behavior)
    score += (post_residual as f64) * 0.5;

    // 5. Mean residual balancing
    // Avoid bins that deviate negatively from the average residual (keep bins uniform)
    if (post_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
