pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Core objective: Minimize residual space (Best Fit), but penalize fragmentation
    // based on lookahead and stream progress.
    let mut score = post * post;

    // Penalty for creating a 'near-empty' bin early in the stream.
    // If we are at the beginning, we want to pack tightly.
    // If we are at the end, we care less about fragmentation.
    let fragmentation_penalty = (1.0 - progress) * (bin_capacity as f64 - post) * 2.5;
    score += fragmentation_penalty;

    // Lookahead coupling: If the next item is large, avoid leaving small residuals
    // that won't accommodate future items.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        // If the current post_residual is smaller than the next item, 
        // we essentially waste that space for the next step.
        if (post_residual as f64) < next {
            score += (next - post) * 10.0;
        }
    }

    // Encourage using existing bins over opening new ones, 
    // but allow new bin opening if the fit is exceptionally poor (high post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open a new bin if the current open bins are very full (mean_residual is low).
        // If mean_residual is high, we should have used an existing bin.
        score += mean_residual * 5.0;

        // If we have many fitting bins, opening a new one is almost always bad.
        score += (fitting_bins_count as f64) * 50.0;
    } else {
        // Penalize bins that are becoming "orphaned" (very low residual, hard to fill).
        // This encourages using bins that have enough space for the next_item_size.
        if post_residual < 10 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
