    let mut score = post_res + dead_space_penalty + lookahead_penalty + closure_incentive + new_bin_base;

    // Favor bins that are already "tight" if we have many fitting bins.
    if fitting_bins_count > 1 {
        score += (bin_capacity - bin_residual) as f64 * 0.1;
