pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the post_residual (Best Fit), but we penalize creating "dead zones"
    // (gaps too small for any likely future item).
    let mut score = post_residual as f64;

    // 1. Penalize creating small unusable gaps (Dead space < 10 is usually wasted).
    if post_residual < 10 && post_residual > 0 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead logic: If the next item fits into this post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Global State: If we have many open bins, prioritize filling existing ones 
    // to keep the bin count low. If few bins are open, we can be more picky.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (open_bins_count as f64) * 2.0 * (1.0 - fill_ratio);

    // 4. Thresholding: If this is the only bin that fits the current item, 
    // we should strongly consider it unless the post_residual is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. New Bin Logic: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the current mean_residual is very low (implying we are 
    // struggling to fit things into existing bins) or if we are at the start of the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Penalize opening new bins as the process nears completion.
        score += 30.0 + (progress * 50.0);

        // If we have many open bins that are nearly empty, don't open another one.
        if mean_residual > 30.0 {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
