            score -= 15.0; // Reward bins that can accommodate the next item
        }
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if current
    // fitting options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty for opening a new bin if we have options
            score += 60.0;
        } else {
            // Low penalty if we have no choice
            score -= 10.0;
        }
    }

    // 5. Global Density Balancing:
    // As the stream progresses, favor packing bins more tightly.
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

