    // 5. Global Efficiency: As the stream progresses, prioritize closing bins
    // by rewarding bins that are nearly filled.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // 6. Last Chance Logic: If this is the only bin that fits the item, 
    // reduce penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
