pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) that are too small to fit common future items.
    // We use a non-linear penalty: smaller post_residual is worse if it falls in the "useless" range (1-9).
    let dead_space_penalty = if post_residual < 10 { 
        (10.0 - post) * 5.0 
    } else { 
        0.0 
    };

    // Reward placing items into bins that bring the residual closer to the mean_residual
    // to keep bins balanced.
    let balance_reward = (post - mean_residual).abs() * 0.5;

    // Lookahead logic: if next_item_size is large, avoid leaving a small post_residual.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 2.0
    } else {
        0.0
    };

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is a new bin. 
    // We heavily penalize this unless the fitting_bins_count is 0 or the current bin is extremely inefficient.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            50.0 + (progress * 20.0)
        } else {
            0.0
        }
    } else {
        0.0
    };

    // Base score: prioritize smaller post_residual (Best Fit), but adjust by penalties.
    let mut score = post + dead_space_penalty + balance_reward + lookahead_penalty + new_bin_penalty;

    // If we are near the end of the stream, prioritize closing bins (lower residual) over opening new ones.
    if progress > 0.9 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
