pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining after placement.
    // Minimizing this naturally leads to Best-Fit behavior.
    let mut score = post;

    // Penalty for creating a "sliver" (fragmented space too small for most items).
    // If post_residual is in (0, 10), it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if the next item is large, favor bins that leave enough space
    // for it, but only if we are not near the end of the stream.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Adaptivity: As the stream progresses, become more aggressive about filling existing
    // bins to minimize the total count, even if it creates slightly worse residuals.
    // We penalize opening new bins more heavily as progress increases.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalty is high early on, but increases significantly as we near the end
        // of the stream to prevent opening unnecessary bins.
        score += 30.0 + (progress * 40.0);

        // If there are other bins that could have fit this item, penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // For existing bins, reward placements that keep the bin residual close to 
        // the global mean residual, promoting uniform bin usage.
        let deviation = (post as f64 - mean_residual).abs();
        score -= deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We want to minimize post_residual, but we also want to avoid creating "orphaned" space.

    // 2. Harmonic Class Logic:
    // If post_residual is small, it's often better to fill it tightly.
    // If post_residual is close to next_item_size, we favor that bin.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // 3. Penalty for opening a new bin if other bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // High penalty for opening a new bin if there are bins that can fit the item
        score += 45.0; 
        // If it's the very last item, opening a new bin is unavoidable if no fit exists
        if step_index == total_items - 1 {
            score -= 20.0;
        }
    }

    // 4. Harmonic Thresholding:
    // Penalize post_residual based on whether it falls into "unusable" ranges (e.g., < 10)
    // Small residual space is often wasted; penalize if it's too small to fit any future item (min 10)
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // 5. Fitting Bins Count Coupling:
    // If this is the only bin that fits, we should prioritize it highly (lower score)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Global pressure:
    // As we approach the end of the stream, prioritize closing bins over opening new ones
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
