    // Penalty for creating "dead space": gaps smaller than the smallest possible item (assumed 10)
    // are highly undesirable as they cannot be filled later.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 25.0;
    }

    // Heuristic: If we are forced to open a new bin, penalize it based on how many
    // bins are already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If the next item is large, prioritize a new bin slightly less to save space
        if next_item_size > 60 {
            score += 10.0;
        }
    } else {
        // If the bin is already open, reward placements that leave space for the next item.
        // This is a "Best-Fit" logic refined by lookahead.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0;
            }
        }
    }

    // Pressure to keep bins balanced: penalize deviating significantly from the mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // Critical threshold: if this is the only bin that fits the item, make it highly attractive
    // to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost is the post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalize opening a new bin unless it is strictly necessary or highly advantageous.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty for opening a new bin if there are existing candidates.
            score += 150.0;
        }
    }

    // 3. Lookahead Matching (The "Aggressive" Component):
    // If we have a next item, we want to minimize the gap between the next item and our post_residual.
    // If post_residual is close to next_item_size, we reward it (subtract score).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Ideal scenario: current bin can accommodate the next item perfectly.
            let fit_gap = (post_residual - next_item_size) as f64;
            score -= (50.0 - fit_gap * 0.5);
        } else {
            // If post_residual is too small for the next item, we penalize it.
            score += 20.0;
        }
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that are significantly "emptier" than the current average.
    // This discourages "straggler" bins that are hard to fill later.
    if post_residual as f64 > mean_residual * 1.2 {
        score += 10.0;
    }

    // 5. Progression scaling:
    // As we reach the end of the stream, prioritize packing items into existing bins more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 5.0;

    score
}
